-- Praxis SLP is now a fixed bank of 365 questions, like Security+, instead of questions
-- written by Claude every night. At one a day that's a year of questions before any repeat.
--
-- The rotation starts on 2026-10-21, the first day Praxis questions were served, and the
-- six questions served so far (2026-10-21 through 2026-10-26) are kept as seq 1-6 in the
-- order they ran. So a one-a-day reader's past days and answers stay exactly as they were.
-- The other 359 are below, rotating through the 34 categories in sort order, with correct
-- answers spread evenly over A-D.

-- Stop brewing. The daily-question edge function is gone.
select cron.unschedule('daily-praxis-question')
where exists (select 1 from cron.job where jobname = 'daily-praxis-question');

-- Keep the six served questions; drop anything the nightly job wrote after them.
delete from public.daily_questions
where exam = 'praxis-slp' and id not in (1, 3, 4, 5, 6, 7);

update public.daily_questions q
set seq = r.seq, question_date = null, position = null
from (
  select id, row_number() over (order by question_date, position) as seq
  from public.daily_questions
  where exam = 'praxis-slp'
) r
where q.id = r.id;

update public.exams set kind = 'bank', starts_on = '2026-10-21' where slug = 'praxis-slp';

-- These let app builds from before 2026-10-26 read Praxis rows straight from the table
-- by date. No row has a date any more, so they match nothing; the app reads through
-- todays_questions() and past_questions().
drop policy "The current question is public" on public.daily_questions;
drop policy "Signed-in users can read past questions" on public.daily_questions;

insert into public.daily_questions
  (exam, seq, category_id, question, choice_a, choice_b, choice_c, choice_d, correct_answer, explanation, model)
select 'praxis-slp', v.seq, c.id, v.question, v.a, v.b, v.c, v.d, v.correct, v.explanation, 'claude-opus-5-5'
from (values
  (7, 'dysphagia-assessment', 'A clinical swallow evaluation shows no coughing or throat clearing with thin liquids, but the patient has had recurrent pneumonia. Why is an instrumental assessment still needed?', 'Bedside exams overestimate aspiration risk', 'A bedside exam can''t detect silent aspiration', 'Instrumental exams are only used for solids', 'Recurrent pneumonia rules out dysphagia', 'B', 'Silent aspiration produces no outward cough, so it can be missed at bedside. VFSS or FEES can show material entering the airway.'),
  (8, 'ethics', 'An SLP tells a parent, ''If your son comes twice a week, I guarantee he''ll stop stuttering by summer.'' Which ethical problem does this raise?', 'Guaranteeing treatment results is prohibited', 'SLPs may not provide treatment for fluency disorders in children', 'Families may not be told how often their child should attend', 'Prognosis must never be discussed with parents or caregivers', 'A', 'The ASHA Code of Ethics prohibits guaranteeing the results of any treatment. SLPs may give a reasonable prognosis.'),
  (9, 'voice-treatment', 'A 35-year-old elementary teacher has bilateral vocal fold nodules and a hoarse voice by the end of each school day. What is the most appropriate first-line treatment?', 'Behavioral voice therapy, including vocal hygiene', 'Surgical removal of the nodules before any therapy', 'Complete voice rest for three months', 'Whispering in place of normal speech at work', 'A', 'Nodules are a hyperfunctional lesion that usually respond to behavioral voice therapy, which is first-line care. Long voice rest is rarely needed, and forceful whispering can strain the folds.'),
  (10, 'autism-assessment', 'Under DSM-5, autism spectrum disorder requires persistent deficits in which areas?', 'Expressive language and speech sound production', 'Social communication, and restricted, repetitive behaviors', 'Intellectual functioning and adaptive behavior skills', 'Sustained attention, impulsivity, and hyperactivity', 'B', 'Both domains are required: social communication and interaction, and restricted, repetitive patterns of behavior, interests, or activities. Language and intellectual disability are listed as specifiers.'),
  (11, 'motor-speech-treatment', 'A 4-year-old with childhood apraxia of speech is treated with integral stimulation (''watch me, listen to me''), simultaneous production, and tactile cues that are faded as accuracy improves. Which approach is this?', 'Dynamic Temporal and Tactile Cueing (DTTC)', 'Cycles approach', 'Minimal pairs therapy', 'Nonspeech oral motor exercises (NSOME)', 'A', 'DTTC adjusts cue level and timing moment to moment, moving from simultaneous production to independent production. Cycles and minimal pairs target phonological patterns.'),
  (12, 'hearing', 'An audiogram shows air conduction thresholds of 45 dB HL and bone conduction thresholds of 5 dB HL across frequencies in the right ear. What type of hearing loss is this?', 'Sensorineural', 'Mixed', 'Central', 'Conductive', 'D', 'Normal bone conduction with an air-bone gap greater than 10 dB means the inner ear is working and the loss is in the outer or middle ear. Sensorineural loss shows no air-bone gap.'),
  (13, 'child-language-assessment', 'A 5-year-old who has been learning English for one year scores low on a standardized English vocabulary test normed on monolingual children. Which approach best tells a language difference from a disorder?', 'Repeating the same standardized test in six months', 'Dynamic assessment with a test-teach-retest format', 'Reporting the low score as evidence of a disorder', 'Using the test norms for a younger age group', 'B', 'Dynamic assessment measures how readily the child learns with teaching (modifiability), which is less biased by limited exposure to English. Using a monolingual norm group misrepresents a bilingual child.'),
  (14, 'cognitive-treatment', 'An SLP teaches a person with Alzheimer''s disease to remember to use her walker by asking her to recall the information at gradually longer intervals. Which technique is this?', 'Spaced retrieval', 'Errorless learning alone', 'Reminiscence therapy', 'Attention process training', 'A', 'Spaced retrieval practices recall of target information over increasing time intervals, relying on preserved procedural memory. It''s often combined with errorless learning.'),
  (15, 'research-ebp', 'Which source generally gives the highest level of evidence for a treatment decision?', 'A detailed single case study', 'A meta-analysis of well-designed randomized controlled trials', 'Expert opinion from a panel of experienced, respected clinicians', 'A large cross-sectional survey of clinicians', 'B', 'Systematic reviews and meta-analyses of RCTs sit at the top of most evidence hierarchies. Expert opinion and case reports are the lowest levels.'),
  (16, 'ssd-treatment', 'A child uses velar fronting. The SLP has him say ''key'' and ''tea'' and shows that saying the wrong one changes the meaning. Which approach is this?', 'Maximal oppositions', 'Cycles approach', 'Traditional articulation therapy', 'Minimal pairs (minimal oppositions)', 'D', 'Minimal pairs contrast the target and the child''s error sound in words differing by one sound, showing how the error causes confusion. Maximal oppositions contrast sounds that differ in many features.'),
  (17, 'motor-speech-assessment', 'A patient has hypernasality, nasal emission, a breathy voice, and a weak tongue with visible atrophy and fasciculations. Which dysarthria type is most likely?', 'Spastic', 'Flaccid', 'Ataxic', 'Hyperkinetic', 'B', 'Weakness, atrophy, and fasciculations point to lower motor neuron damage, which causes flaccid dysarthria. Spastic dysarthria comes from bilateral upper motor neuron damage and has a strained voice.'),
  (18, 'dysphagia-treatment', 'Videofluoroscopy shows a delayed pharyngeal swallow, with liquid spilling into the airway before the swallow. Which posture is most often tried first?', 'Head tilt back', 'Lying on the back', 'Chin tuck (chin down)', 'Head tilt toward the stronger side', 'C', 'A chin tuck widens the valleculae and narrows the airway entrance, helping hold the bolus before the swallow triggers. Head tilt back speeds oral transit but opens the airway.'),
  (19, 'legislation', 'Under IDEA, which part covers early intervention services for infants and toddlers from birth to age 3?', 'Part C', 'Part A', 'Part B', 'Part D', 'A', 'Part C covers early intervention through an IFSP. Part B covers special education for children ages 3 through 21 through an IEP.'),
  (20, 'fluency-assessment', 'Which disfluency is classified as stuttering-like rather than typical?', 'Interjection, as in ''I, um, want it''', 'Revision, as in ''I want, I need a cup''', 'Phrase repetition, as in ''I want, I want it''', 'Part-word repetition, as in ''b-b-ball''', 'D', 'Stuttering-like disfluencies include part-word and single-syllable word repetitions, prolongations, and blocks. Interjections, revisions, and phrase repetitions are typical.'),
  (21, 'aphasia-treatment', 'To help a patient name ''apple'', the SLP has him describe its group, use, properties, location, and associations using a chart. Which treatment is this?', 'Phonological components analysis', 'Semantic feature analysis', 'Melodic intonation therapy', 'Script training', 'B', 'Semantic feature analysis strengthens a word''s meaning network to aid retrieval. Phonological components analysis cues sound features such as the first sound and syllable count.'),
  (22, 'aac', 'An SLP evaluates a client''s motor, sensory, cognitive, and language skills, then chooses an AAC system whose features fit them. What is this process called?', 'Feature matching', 'Candidacy screening', 'Core vocabulary selection', 'Aided language modeling', 'A', 'Feature matching compares a person''s skills and needs to the features of AAC options. Candidacy models that require prerequisite skills are outdated.'),
  (23, 'voice-resonance-assessment', 'Laryngoscopy shows small, symmetrical bumps on both vocal folds at the junction of the front and middle thirds in a teacher with a hoarse, breathy voice. What is the most likely finding?', 'Reinke''s edema', 'Vocal fold nodules', 'Contact granuloma', 'Laryngeal papilloma', 'B', 'Nodules are bilateral and form at the point of greatest impact, between the anterior and middle thirds. Granulomas form at the back, on the vocal processes.'),
  (24, 'cultural-linguistic', 'A 6-year-old who speaks African American English says ''She nice'' and ''They be playing after school.'' How should the SLP view these utterances?', 'As rule-governed dialect features, not errors', 'As signs of a language disorder', 'As grammatical errors to target in therapy', 'As evidence of a speech sound disorder', 'A', 'Zero copula and habitual ''be'' are rule-governed features of AAE. Scoring dialect features as errors leads to overidentification of disorder.'),
  (25, 'cognitive-assessment', 'In the emergency department, a patient with a head injury scores 7 on the Glasgow Coma Scale. How is this injury classified?', 'Mild brain injury', 'Moderate brain injury', 'Normal consciousness', 'Severe brain injury', 'D', 'The Glasgow Coma Scale ranges from 3 to 15, adding eye, verbal, and motor responses. A score of 8 or below is severe, 9 to 12 moderate, and 13 to 15 mild.'),
  (26, 'autism-treatment', 'An SLP follows a 2-year-old''s lead in play, uses natural rewards such as continuing the game, and targets developmental skills like joint attention. What category of intervention is this?', 'Discrete trial training at a table with prompts', 'Facilitated communication with hand-over-hand support', 'Naturalistic developmental behavioral intervention (NDBI)', 'Nonspeech oral motor therapy before speech', 'C', 'NDBIs such as JASPER, the Early Start Denver Model, and Project ImPACT combine developmental science with behavioral principles in natural play routines. Discrete trial training is adult-directed and structured.'),
  (27, 'cleft-craniofacial', 'After palate repair, a 5-year-old replaces oral stops with glottal stops and uses pharyngeal fricatives for /s/. How should these errors be managed?', 'With speech therapy, because they are learned compensatory errors', 'With surgery only, because they are caused by structure', 'With blowing exercises to strengthen the velum', 'By waiting, because they will resolve on their own after surgery', 'A', 'Compensatory errors are learned placements made to work around past or current VPI, and they need speech therapy. They often persist even after the structure is fixed.'),
  (28, 'speech-science', 'What is the fundamental frequency of the voice?', 'The loudness of the voice', 'The resonant frequencies of the vocal tract', 'The rate of vocal fold vibration, heard as pitch', 'The amount of airflow through the glottis', 'C', 'Fundamental frequency is the number of vibration cycles per second, in hertz, and is perceived as pitch. Vocal tract resonances are formants.'),
  (29, 'literacy', 'Which phonological awareness skill typically develops last?', 'Recognizing whether two words rhyme', 'Clapping the syllables in multisyllabic words', 'Identifying the first sound in a spoken word', 'Phoneme manipulation, such as ''stop'' without /t/', 'D', 'Phonological awareness generally moves from larger units (words, syllables, rhymes) to individual phonemes, with phoneme deletion and substitution coming last.'),
  (30, 'counseling-collaboration', 'During a session, the parent of a child who stutters becomes tearful and says she''s been feeling very depressed for months. What should the SLP do?', 'Provide counseling to treat her depression herself', 'Listen with empathy and refer her for mental health care', 'Ignore the comment and continue with the session', 'Tell her to focus only on her child''s needs', 'B', 'SLPs counsel about communication disorders and their effects, but treating depression is outside their scope. They should respond with empathy and refer.'),
  (31, 'neuroscience', 'Broca''s area is located in which part of the brain?', 'Left inferior frontal gyrus', 'Left superior temporal gyrus', 'Right occipital lobe', 'Cerebellum', 'A', 'Broca''s area (Brodmann areas 44 and 45) is in the inferior frontal gyrus of the dominant hemisphere. Wernicke''s area is in the posterior superior temporal gyrus.'),
  (32, 'early-intervention-feeding', 'In Part C early intervention, what is the main role of the SLP during home visits?', 'Coaching caregivers to use strategies in the family''s daily routines', 'Doing therapy with the child while parents wait in another room', 'Teaching the child at a table with flash cards', 'Training the child to sit still for drills', 'A', 'Early intervention emphasizes coaching families in natural environments, since caregivers are with the child far more than the SLP. Direct therapy apart from routines doesn''t build caregiver capacity.'),
  (33, 'genetic-syndromes', 'A child with Down syndrome has frequent ear infections and fluctuating hearing. Which language profile is most typical of Down syndrome?', 'Receptive language far weaker than expressive', 'Expressive language weaker than receptive language', 'Language skills well above cognitive level', 'Normal grammar with severe vocabulary loss', 'B', 'Children with Down syndrome usually have stronger receptive than expressive language, with particular difficulty in grammar and speech intelligibility. Hearing should be monitored because conductive loss is common.'),
  (34, 'head-neck-laryngectomy', 'A patient with a total laryngectomy and a tracheoesophageal puncture covers his stoma to speak. Where does the sound come from?', 'Lung air through the prosthesis vibrates the PE segment', 'The vocal folds vibrate as they did before surgery', 'An external device held against the neck makes the sound', 'Air swallowed into the stomach is burped back up', 'A', 'In TE speech, covering the stoma sends lung air through a one-way valve into the esophagus, where the PE segment vibrates. The larynx was removed, so there are no vocal folds.'),
  (35, 'ssd-assessment', 'During an evaluation, a 4-year-old produces /s/ correctly in isolation and syllables when the SLP gives a model and a visual cue, but not in spontaneous speech. What does this finding most strongly suggest?', 'The child likely has a motor speech disorder affecting /s/', 'The sound should be the last one targeted in therapy', 'The child''s errors are most likely caused by a hearing loss', 'The sound is stimulable, which is a favorable sign for change', 'D', 'Stimulability means a child can produce a sound with support, and stimulable sounds are generally more likely to improve. It doesn''t point to a motor speech disorder or hearing loss on its own.'),
  (36, 'typical-development', 'An SLP calculates mean length of utterance in morphemes from three utterances: ''Doggie run.'' ''Mommy eats cookies.'' ''I want juice.'' What is the MLU?', '2.67', '3.00', '3.33', '4.00', 'C', '''Doggie run'' has 2 morphemes, ''Mommy eats cookies'' has 5 (eat + -s, cookie + -s), and ''I want juice'' has 3, so 10 divided by 3 is 3.33. Counting words instead of morphemes gives 2.67.'),
  (37, 'fluency-treatment', 'An adult who stutters is taught that, while still in a moment of stuttering, he should slow down and ease out of it smoothly instead of forcing through. Which stuttering modification technique is this?', 'Cancellation', 'Preparatory set', 'Pull-out', 'Easy onset', 'C', 'A pull-out modifies the stutter during the moment itself. A cancellation happens after the stuttered word, and a preparatory set happens before an anticipated stutter.'),
  (38, 'anatomy-physiology', 'Which muscle is mainly responsible for raising pitch by lengthening and tensing the vocal folds?', 'Cricothyroid', 'Thyroarytenoid', 'Lateral cricoarytenoid', 'Interarytenoid', 'A', 'The cricothyroid tilts the thyroid and cricoid cartilages, stretching the folds to raise pitch, and is supplied by the superior laryngeal nerve. The lateral cricoarytenoid and interarytenoids adduct the folds.'),
  (39, 'aphasia-assessment', 'After a left frontal stroke, a 64-year-old speaks in short, effortful, telegraphic phrases. He understands conversation well but can''t repeat sentences. He is frustrated by his errors. Which aphasia type fits best?', 'Transcortical motor aphasia', 'Conduction aphasia', 'Anomic aphasia', 'Broca''s aphasia', 'D', 'Nonfluent speech, relatively good comprehension, and poor repetition point to Broca''s aphasia. Transcortical motor aphasia is also nonfluent, but repetition is preserved.'),
  (40, 'child-language-treatment', 'An SLP models the target ''is + -ing'' many times while playing with a 4-year-old (''The bear is jumping. Now he is sleeping.'') but doesn''t require the child to say it. Which approach is this?', 'Focused stimulation', 'Drill play', 'Mand-model', 'Sentence combining', 'A', 'Focused stimulation gives dense, meaningful models of a target without requiring imitation. Mand-model requires a response from the child.'),
  (41, 'dysphagia-assessment', 'On the Penetration-Aspiration Scale, what does a score of 8 indicate?', 'Material doesn''t enter the airway', 'Material enters the airway, stays above the folds, and is ejected', 'Material passes below the vocal folds with no effort to eject it', 'Material passes below the vocal folds and is coughed out', 'C', 'A score of 8 means silent aspiration: material goes below the true vocal folds and the patient makes no attempt to clear it. A score of 1 means no airway entry.'),
  (42, 'ethics', 'An SLP at a new hospital job is asked to start performing FEES, but she has never been trained in it. What should she do?', 'Perform it, since FEES is within the SLP scope of practice', 'Ask a nurse to perform the procedure for her', 'Decline to perform it until she gets appropriate training and competence', 'Perform it but document that she is unsure of the technique', 'C', 'Being within the scope of practice isn''t the same as being personally competent. The Code requires SLPs to provide only services they''re qualified for by education, training, and experience.'),
  (43, 'voice-treatment', 'A patient with vocal fold irritation clears his throat dozens of times a day. What is the best replacement behavior to teach?', 'A strong cough', 'Whispering for the rest of the day', 'Humming loudly', 'A hard swallow or a sip of water', 'D', 'Throat clearing and coughing slam the vocal folds together. A hard swallow or a sip of water clears the sensation without that impact.'),
  (44, 'autism-assessment', 'Which finding at a 12-month well-child visit is most concerning as an early sign of autism?', 'Saying only one or two meaningful words', 'No response to name and no pointing to show things', 'Babbling strings of syllables without real words', 'Walking only while holding on to furniture', 'B', 'Not responding to name and not using gestures such as pointing are early red flags. One or two words and cruising are typical at 12 months.'),
  (45, 'motor-speech-treatment', 'Based on principles of motor learning, which feedback schedule best supports long-term retention of speech motor skills?', 'Reduced-frequency or delayed feedback', 'Immediate feedback after every attempt', 'No practice between sessions', 'Feedback only from a mirror', 'A', 'Frequent, immediate feedback helps early accuracy, but reduced or delayed feedback leads to better retention and transfer. Practice between sessions also helps.'),
  (46, 'hearing', 'An audiogram shows air conduction thresholds of 60 dB HL and bone conduction thresholds of 30 dB HL. What type of hearing loss is this?', 'Conductive', 'Sensorineural', 'Mixed', 'Normal hearing', 'C', 'Bone conduction is abnormal (sensorineural component) and there''s also an air-bone gap (conductive component), so the loss is mixed.'),
  (47, 'child-language-assessment', 'A child earns a standard score of 70 on a test with a mean of 100 and a standard deviation of 15. How far below the mean is this score?', '1 standard deviation', '2 standard deviations', '1.5 standard deviations', '3 standard deviations', 'B', 'Thirty points below the mean divided by a standard deviation of 15 equals 2 standard deviations. A score of 85 would be 1 standard deviation below.'),
  (48, 'cognitive-treatment', 'When teaching new routines to people with significant memory impairment, why is errorless learning recommended?', 'It requires the person to notice and correct their own mistakes', 'Errors are hard for them to forget, so they get relearned', 'It speeds learning by encouraging the person to guess', 'It works only for people with mild memory impairment', 'B', 'People with poor explicit memory can''t easily recall which attempts were wrong, so errors get reinforced. Errorless learning prevents mistakes by giving support before errors happen.'),
  (49, 'research-ebp', 'An SLP measures a behavior at baseline, introduces treatment, withdraws it, then reintroduces it. Which design is this?', 'ABAB withdrawal design', 'Multiple baseline design', 'Randomized controlled trial', 'Cross-sectional design', 'A', 'In an ABAB design, the behavior should change with treatment and return toward baseline when treatment is withdrawn, showing experimental control. It is a single-subject design.'),
  (50, 'ssd-treatment', 'An SLP pairs words such as ''mop'' and ''shop'', choosing sounds that differ in place, manner, and voicing, to treat a child with many sound errors. Which approach is this?', 'Minimal pairs', 'Multiple oppositions', 'Core vocabulary', 'Maximal oppositions', 'D', 'Maximal oppositions contrast sounds that differ on several features and often include sounds the child doesn''t produce. Gierut found this can lead to broad system-wide change.'),
  (51, 'motor-speech-assessment', 'After bilateral strokes, a patient speaks slowly with a strained-strangled voice, low pitch, hypernasality, and imprecise consonants. Which dysarthria type fits best?', 'Flaccid', 'Spastic', 'Hypokinetic', 'Ataxic', 'B', 'A strained-strangled voice with slow rate is typical of spastic dysarthria from bilateral upper motor neuron damage. Flaccid dysarthria usually has a breathy voice.'),
  (52, 'dysphagia-treatment', 'A patient has weakness on the right side of the pharynx, with residue in the right pyriform sinus. Which posture is most appropriate?', 'Turning the head to the left', 'Tilting the head back', 'Turning the head to the right', 'Chin up with mouth open', 'C', 'Turning toward the weak side closes off that side of the pharynx, so the bolus goes down the stronger side. It also reduces UES pressure.'),
  (53, 'legislation', 'How does an Individualized Family Service Plan (IFSP) differ from an IEP?', 'It applies only to children ages 5 through 21', 'It includes family outcomes and services in natural settings', 'It is written by the classroom teacher alone', 'It is reviewed only once every three years by the school', 'B', 'IFSPs focus on the family and on services in everyday settings such as the home. They serve children from birth to 3 and are reviewed every six months.'),
  (54, 'fluency-assessment', 'Researchers often use a threshold of how many stuttering-like disfluencies per 100 syllables to help identify stuttering in young children?', '3 or more', '1 or more', '10 or more', '25 or more', 'A', 'Children who stutter usually produce 3 or more stuttering-like disfluencies per 100 syllables. Typically fluent children usually produce fewer.'),
  (55, 'aphasia-treatment', 'A patient with severe nonfluent aphasia, good comprehension, and poor repetition is taught to intone short phrases while tapping his left hand. Which treatment is this?', 'Constraint-induced language therapy', 'Response elaboration training', 'Semantic feature analysis', 'Melodic intonation therapy', 'D', 'Melodic intonation therapy uses intoned speech and left-hand tapping, thought to engage right-hemisphere networks. It''s for nonfluent aphasia with fairly good comprehension.'),
  (56, 'aac', 'A parent worries that using an AAC device will stop her 3-year-old from learning to talk. What does research show?', 'AAC usually stops speech development', 'AAC doesn''t hinder speech and often supports it', 'AAC should be delayed until the child turns 5', 'AAC only helps children who already talk', 'B', 'Studies find AAC doesn''t keep children from developing speech, and many show increases in speech. Delaying AAC withholds a way to communicate.'),
  (57, 'voice-resonance-assessment', 'A 60-year-old woman who has smoked for 40 years has a very low-pitched, rough voice. Both vocal folds look swollen and floppy along their length. What is the most likely diagnosis?', 'Reinke''s edema', 'Vocal fold nodules', 'Unilateral vocal fold paralysis', 'Contact ulcers', 'A', 'Reinke''s edema is fluid in the superficial lamina propria, strongly linked to smoking, and it lowers pitch. Nodules are smaller, localized lesions.'),
  (58, 'cultural-linguistic', 'A child who speaks African American English says ''tes'' for ''test'' and ''baf'' for ''bath''. How should these be scored?', 'As dialect features, not errors', 'As final consonant deletion errors', 'As a lisp', 'As signs of hearing loss', 'A', 'Final cluster reduction and /f/ for word-final /θ/ are typical AAE phonological features. They shouldn''t be counted as speech sound errors.'),
  (59, 'cognitive-assessment', 'A patient with a TBI is alert and follows simple commands inconsistently. He isn''t agitated, but he''s very distractible, can''t learn new information, and needs constant redirection. Which Rancho Los Amigos level fits best?', 'Level V, confused-inappropriate, non-agitated', 'Level II, generalized response', 'Level IV, confused-agitated', 'Level VIII, purposeful-appropriate', 'A', 'At Level V, the person is calmer than at Level IV but still confused and highly distractible, with poor new learning. Level IV involves agitation.'),
  (60, 'autism-treatment', 'An autistic 5-year-old has meltdowns when moving between activities. Which strategy is most likely to help?', 'Removing all routines from his day', 'A visual schedule that shows what comes next', 'Giving longer verbal explanations before each change', 'Withholding preferred activities until he''s calm', 'B', 'Visual schedules make transitions predictable and use relatively strong visual processing. Long verbal explanations may add to the load.'),
  (61, 'cleft-craniofacial', 'Which speech characteristic in a child with velopharyngeal insufficiency is an obligatory error that needs physical management?', 'Hypernasality from an incomplete velopharyngeal seal', 'Glottal stops in place of oral stops', 'Pharyngeal fricatives in place of /s/', 'Nasal snorting produced in place of /s/ and /z/', 'A', 'Obligatory errors come directly from the structural problem and won''t change with therapy alone. Compensatory errors are learned and respond to therapy.'),
  (62, 'speech-science', 'How do the first two formants relate to vowel production?', 'F1 rises as the tongue rises; F2 rises as the tongue moves back', 'F1 rises as the tongue lowers; F2 rises as the tongue moves forward', 'F1 reflects lip rounding only; F2 reflects voicing', 'Both formants reflect vocal fold vibration', 'B', 'Low vowels such as /a/ have a high F1, and front vowels such as /i/ have a high F2. Formants are vocal tract resonances, separate from vocal fold vibration.'),
  (63, 'literacy', 'According to the Simple View of Reading, reading comprehension is the product of which two components?', 'Phonological awareness and handwriting', 'Vocabulary and spelling', 'Reading speed and vision', 'Decoding and language comprehension', 'D', 'The Simple View of Reading states that comprehension equals decoding times language comprehension. A weakness in either one limits comprehension.'),
  (64, 'counseling-collaboration', 'A client says, ''Nobody at work gives me time to finish my sentences.'' Which response best shows active listening?', '''You should just tell them to wait until you finish.''', '''Everyone feels that way at work sometimes.''', '''It sounds like you feel rushed and frustrated at work.''', '''Let''s get back to our speech exercises now.''', 'C', 'Reflecting the client''s feelings shows understanding and invites more sharing. Giving advice or minimizing can shut down communication.'),
  (65, 'neuroscience', 'Which fiber tract connects Wernicke''s area with Broca''s area?', 'Corpus callosum', 'Corticospinal tract', 'Arcuate fasciculus', 'Optic radiation', 'C', 'The arcuate fasciculus links posterior and anterior language areas, and damage to it is linked to conduction aphasia. The corpus callosum connects the two hemispheres.'),
  (66, 'early-intervention-feeding', 'An SLP helps a family find language-learning chances during bath time, meals, and getting dressed. What approach is this?', 'Clinic-based drill therapy', 'Routines-based intervention', 'Discrete trial training', 'Pull-out therapy', 'B', 'Routines-based intervention embeds goals in the family''s everyday activities, which provides many practice opportunities. It fits the natural environments principle of Part C.'),
  (67, 'genetic-syndromes', 'A boy has intellectual disability, gaze aversion, social anxiety, and fast speech with frequent repetitions of words and phrases. The cause is a mutation of the FMR1 gene. Which syndrome is this?', 'Down syndrome', 'Fragile X syndrome', 'Williams syndrome', 'Prader-Willi syndrome', 'B', 'Fragile X is the most common inherited cause of intellectual disability and often includes perseverative, cluttered speech and autism features. It is X-linked, so boys are usually more affected.'),
  (68, 'head-neck-laryngectomy', 'Which alaryngeal speech method uses air brought into the esophagus from the mouth and released to vibrate the pharyngoesophageal segment, with no device?', 'Tracheoesophageal speech', 'Electrolarynx speech', 'Whispered speech', 'Esophageal speech', 'D', 'Esophageal speech needs no device or surgery, but it''s the hardest method to learn, and phrases are short. TE speech uses lung air through a prosthesis.'),
  (69, 'ssd-assessment', 'Which phonological process is still common in typically developing children at age 4;6?', 'Final consonant deletion', 'Gliding of liquids', 'Reduplication', 'Velar fronting', 'B', 'Gliding of /r/ and /l/ often persists until about 5 to 6 years. Final consonant deletion and reduplication are usually gone by about 3, and velar fronting by about 3;6.'),
  (70, 'typical-development', 'Two-word combinations usually begin when a toddler has an expressive vocabulary of about 50 words. Around what age does this typically happen?', '9 to 12 months', '18 to 24 months', '12 to 15 months', '30 to 36 months', 'B', 'Children usually reach about 50 words and start combining words between 18 and 24 months, often with a vocabulary spurt. First words typically appear around 12 months.'),
  (71, 'fluency-treatment', 'Which technique is a core part of fluency shaping rather than stuttering modification?', 'Voluntary stuttering to reduce fear', 'Gentle voicing onsets with extended syllables', 'Pull-outs from stuttered moments', 'Identifying and analyzing each stuttering moment', 'B', 'Fluency shaping changes the overall speech pattern with targets such as easy onsets and prolonged speech. Voluntary stuttering, pull-outs, and identification are stuttering modification techniques.'),
  (72, 'anatomy-physiology', 'Which muscle is the primary muscle of inspiration?', 'Internal intercostals', 'Rectus abdominis', 'Diaphragm', 'External obliques', 'C', 'The diaphragm contracts and lowers to expand the thoracic cavity, supplied by the phrenic nerve. The internal intercostals and abdominal muscles assist forced expiration.'),
  (73, 'aphasia-assessment', 'A patient speaks fluently with normal rate and melody but uses many paraphasias and neologisms. She doesn''t follow simple commands, can''t repeat, and seems unaware of her errors. Damage most likely involves which area?', 'Left inferior frontal gyrus (Broca''s area)', 'Posterior superior temporal gyrus', 'Arcuate fasciculus only', 'Right inferior parietal lobule', 'B', 'This is Wernicke''s aphasia, linked to damage in the posterior superior temporal gyrus of the dominant hemisphere. Inferior frontal damage produces a nonfluent aphasia.'),
  (74, 'child-language-treatment', 'A toddler reaches toward a toy on a high shelf. The SLP pauses and looks at the child expectantly, waiting for a word before helping. Which milieu teaching technique is this?', 'Mand-model', 'Incidental teaching', 'Time delay', 'Expansion', 'C', 'Time delay uses an expectant pause to prompt the child to communicate. In mand-model, the adult gives a direct verbal prompt such as ''Tell me what you want.'''),
  (75, 'dysphagia-assessment', 'Which is an advantage of FEES over videofluoroscopy?', 'It shows the oral phase of the swallow clearly', 'It gives an unbroken view at the height of the swallow', 'It shows the esophageal phase in detail', 'It is portable, uses no radiation, and shows secretions', 'D', 'FEES is portable, uses no radiation, and directly shows secretions and pharyngeal residue. It can''t show the oral phase, and the view whites out at the height of the swallow.'),
  (76, 'ethics', 'An SLP repeatedly notices a coworker who seems impaired by alcohol while treating patients. What is the most appropriate action?', 'Report the concern to the appropriate supervisor or authority', 'Ignore it, since alcohol use is a personal matter', 'Discuss the concern with the coworker''s patients', 'Post a warning to other colleagues about it on social media', 'A', 'The Code requires taking action when a professional''s impairment may endanger the people served. Telling patients or posting publicly would violate confidentiality and professionalism.'),
  (77, 'voice-treatment', 'Which voice therapy approach trains easy phonation with a focus on feeling vibration in the lips and front of the face?', 'Vocal function exercises', 'Confidential voice therapy', 'Resonant voice therapy', 'Pushing and pulling exercises', 'C', 'Resonant voice therapy uses forward-focused vibration to achieve strong voice with minimal vocal fold impact. Vocal function exercises use a set sequence of sustained vowels and pitch glides.'),
  (78, 'autism-assessment', 'What is the M-CHAT-R/F designed to do?', 'Diagnose autism in school-age children', 'Measure expressive vocabulary in toddlers and preschoolers', 'Assess articulation in preschoolers', 'Screen toddlers 16 to 30 months old for autism risk', 'D', 'The M-CHAT-R/F is a parent-report screener with a follow-up interview for toddlers. A positive screen calls for a diagnostic evaluation; it isn''t a diagnosis.'),
  (79, 'motor-speech-treatment', 'For retention and generalization in motor speech treatment, which practice schedule is generally best once a child can produce the targets?', 'Blocked practice of one target at a time', 'Practice of nonspeech movements', 'Random practice, mixing different targets', 'A single long session each month', 'C', 'Random practice is harder during sessions but leads to better retention than blocked practice. Distributed practice works better than rare, long sessions.'),
  (80, 'hearing', 'A 3-year-old''s tympanogram is flat (Type B) with a normal ear canal volume. What does this most likely indicate?', 'Normal middle ear function', 'Fluid in the middle ear', 'A perforated eardrum', 'Ossicular discontinuity', 'B', 'A flat tracing with normal volume suggests middle ear effusion, as with otitis media. A flat tracing with a large volume suggests a perforation or an open tube.'),
  (81, 'child-language-assessment', 'A child earns a standard score of 85 (mean 100, SD 15). Which percentile rank is closest?', '5th percentile', '34th percentile', '50th percentile', '16th percentile', 'D', 'A score 1 standard deviation below the mean falls at about the 16th percentile on a normal curve. The 50th percentile is the mean.'),
  (82, 'cognitive-treatment', 'Which intervention best supports conversation for a person with moderate Alzheimer''s disease?', 'Daily drills to restore her recent memory', 'Reality orientation quizzes about the date and place', 'A memory book with photos and short captions about her life', 'Long, open-ended questions about recent events in her life', 'C', 'Memory books and other external aids use preserved reading and recognition to support conversation. Restorative memory drills and quizzing aren''t effective and can cause frustration.'),
  (83, 'research-ebp', 'Treatment starts for one behavior while two others stay in baseline, then each is treated at staggered times. Which design is this?', 'ABAB withdrawal design', 'Multiple baseline across behaviors', 'Alternating treatments design', 'Pretest-posttest group design', 'B', 'A multiple baseline design shows control when each behavior changes only once its treatment begins. It''s useful when withdrawing treatment would be unethical or impossible.'),
  (84, 'ssd-treatment', 'A child substitutes /t/ for /k/, /s/, /ʃ/, and /ʧ/. The SLP contrasts ''tore'' at once with ''core'', ''sore'', ''shore'', and ''chore''. Which approach is this?', 'Minimal pairs', 'Cycles approach', 'Phonetic placement', 'Multiple oppositions', 'D', 'Multiple oppositions treat a phoneme collapse by contrasting one error sound with several targets at once. It''s designed for children who use one sound for many.'),
  (85, 'motor-speech-assessment', 'A patient with cerebellar degeneration has irregular articulatory breakdowns, distorted vowels, and excess and equal stress on syllables. Which dysarthria type is this?', 'Spastic', 'Hypokinetic', 'Flaccid', 'Ataxic', 'D', 'Cerebellar damage causes ataxic dysarthria, with incoordination that shows as irregular breakdowns and scanning speech. The other types come from different parts of the motor system.'),
  (86, 'dysphagia-treatment', 'Which maneuver has the patient hold the larynx at its highest point during the swallow to prolong upper esophageal sphincter opening?', 'Supraglottic swallow', 'Effortful swallow', 'Masako maneuver', 'Mendelsohn maneuver', 'D', 'The Mendelsohn maneuver prolongs laryngeal elevation, which keeps the UES open longer. The supraglottic swallow targets airway closure.'),
  (87, 'legislation', 'Under IDEA, what does least restrictive environment mean?', 'All services are given in a separate special education room', 'Learning with nondisabled peers as much as appropriate', 'Children receive the fewest services the school can offer', 'Parents choose which school building their child attends', 'B', 'LRE requires that children be educated with nondisabled peers to the greatest extent appropriate. Removal happens only when the disability''s nature means supports can''t make the general classroom work.'),
  (88, 'fluency-assessment', 'Which factor increases a preschooler''s risk that stuttering will persist rather than resolve?', 'Being female rather than male', 'Onset at age 2 rather than later', 'Stuttering for only a few months so far', 'A family history of persistent stuttering', 'D', 'Risk factors for persistence include family history of persistent stuttering, male sex, later onset, longer time since onset, and co-occurring speech or language concerns.'),
  (89, 'aphasia-treatment', 'In a therapy group, patients play card games where they must use spoken words to make requests, and gestures and writing aren''t allowed. Treatment runs several hours a day for two weeks. Which approach is this?', 'Promoting Aphasics'' Communicative Effectiveness', 'Supported conversation', 'Melodic intonation therapy', 'Constraint-induced language therapy', 'D', 'CILT constrains communication to speech and uses intensive, massed practice. PACE does the opposite, letting the patient choose any modality.'),
  (90, 'aac', 'Which statement reflects current best practice about who can benefit from AAC?', 'Children must show object permanence before AAC', 'No one is too impaired; there are no prerequisites', 'Only people with intact cognition can use AAC', 'AAC is used only after speech therapy fails', 'B', 'Current practice rejects prerequisite skills for AAC. Everyone communicates, and AAC can be tailored to any level.'),
  (91, 'voice-resonance-assessment', 'After a long intubation, a patient develops a lesion on the posterior vocal folds near the vocal processes. Reflux may also play a role. What is it most likely?', 'Vocal fold nodules', 'Reinke''s edema', 'Contact granuloma', 'Vocal fold cyst', 'C', 'Contact ulcers and granulomas form on the vocal processes of the arytenoids and are linked to intubation, reflux, and hard glottal attacks. Nodules form in the membranous folds.'),
  (92, 'cultural-linguistic', 'A child whose first language is Spanish says ''eschool'' for ''school'' and ''estop'' for ''stop''. What best explains this?', 'A phonological disorder affecting both languages', 'Childhood apraxia of speech affecting clusters', 'A high-frequency hearing loss affecting /s/', 'Spanish, which has no word-initial /s/ clusters', 'D', 'Spanish doesn''t begin words with /s/ + consonant clusters, so speakers often add a vowel before them. This is a typical second-language pattern, not a disorder.'),
  (93, 'cognitive-assessment', 'Which screening tool is generally more sensitive than the MMSE for detecting mild cognitive impairment, partly because it includes executive function tasks?', 'Montreal Cognitive Assessment (MoCA)', 'Glasgow Coma Scale (GCS)', 'Boston Naming Test (BNT-2)', 'Rancho Los Amigos Scale', 'A', 'The MoCA includes executive, visuospatial, and delayed recall items that make it more sensitive to mild impairment. The Glasgow Coma Scale rates consciousness.'),
  (94, 'autism-treatment', 'In the first phase of the Picture Exchange Communication System (PECS), what does the child learn to do?', 'Hand a picture to a partner in exchange for a desired item', 'Build sentences with ''I want'' strips', 'Answer the question ''What do you see?''', 'Point to pictures on a speech-generating device to request', 'A', 'PECS Phase I teaches the basic exchange with physical prompting. Sentence strips and commenting come in later phases.'),
  (95, 'cleft-craniofacial', 'Around what age is cleft palate repair usually done to support speech development?', 'Within the first two weeks of life', 'About 4 to 5 years', 'After the permanent teeth erupt', 'About 9 to 18 months', 'D', 'Palate repair is usually done before about 18 months, often around 9 to 12 months, so velopharyngeal function is in place as speech develops. Cleft lip is often repaired at about 3 months.'),
  (96, 'speech-science', 'On a wideband spectrogram, what do the horizontal axis, the vertical axis, and the darkness show?', 'Frequency, time, and pitch', 'Time, frequency, and intensity', 'Intensity, time, and frequency', 'Time, intensity, and duration', 'B', 'A spectrogram plots time left to right, frequency bottom to top, and intensity as darkness. Formants appear as dark horizontal bands.'),
  (97, 'literacy', 'Which description best fits dyslexia?', 'Poor reading caused mainly by low intelligence', 'Seeing letters backwards from a vision problem', 'Poor understanding of spoken language', 'Trouble with accurate, fluent decoding and spelling', 'D', 'Dyslexia is a specific learning disability with trouble decoding and spelling, usually linked to phonological processing. It isn''t a visual problem or a result of low IQ.'),
  (98, 'counseling-collaboration', 'Parents of a child just diagnosed with hearing loss insist that the test must be wrong. How should the SLP respond?', 'Argue with the parents until they accept the results', 'End services until both parents agree with the diagnosis given', 'Agree that the test result is probably a mistake', 'Recognize a common grief reaction; give patience and information', 'D', 'Denial is a common early reaction to a diagnosis. Patient support and clear information help families move toward acceptance.'),
  (99, 'neuroscience', 'After thyroid surgery, a patient has a breathy voice from a paralyzed vocal fold. Which nerve was most likely damaged?', 'Recurrent laryngeal nerve', 'Hypoglossal nerve (CN XII)', 'Facial nerve', 'Trigeminal nerve', 'A', 'The recurrent laryngeal branch of the vagus nerve supplies all intrinsic laryngeal muscles except the cricothyroid, and it runs near the thyroid gland.'),
  (100, 'early-intervention-feeding', 'During a NICU bottle feeding, a preterm infant splays her fingers, turns pale, and her oxygen saturation drops. What should the SLP do?', 'Keep feeding to finish the full volume', 'Increase the flow rate to shorten the feeding', 'Pause the feeding and let the infant recover', 'Wake the infant up more to continue', 'C', 'Finger splaying, color change, and desaturation are stress cues. Cue-based feeding responds to them by pausing, rather than pushing to finish a volume.'),
  (101, 'genetic-syndromes', 'A child has hypernasal speech, a heart defect, learning difficulties, and a characteristic facial appearance. Which syndrome should the team consider?', 'Fragile X syndrome (FMR1 mutation)', 'Rett syndrome (MECP2 mutation)', 'Angelman syndrome (UBE3A loss)', '22q11.2 deletion (velocardiofacial) syndrome', 'D', '22q11.2 deletion often causes velopharyngeal insufficiency, sometimes with a submucous cleft, along with heart defects and learning problems. It also carries higher risk for psychiatric disorders.'),
  (102, 'head-neck-laryngectomy', 'Which is a main advantage of an electrolarynx for a patient soon after total laryngectomy?', 'It sounds the most natural of all alaryngeal methods', 'It needs no hands to operate', 'It can be learned quickly and used soon after surgery', 'It restores the sense of smell', 'C', 'An electrolarynx is easy to learn and available right away, often with an intraoral tube before the neck heals. Its sound is mechanical, and most models need a hand.'),
  (103, 'ssd-assessment', 'A parent asks how much of their 3-year-old''s speech an unfamiliar listener should be able to understand. Which estimate is most consistent with common intelligibility guidelines?', 'About 25 percent', 'About 50 percent', 'Nearly 100 percent', 'About 75 percent', 'D', 'A common guideline is about 50 percent intelligible to strangers at 2, 75 percent at 3, and nearly 100 percent at 4. Fifty percent would be expected at age 2, not 3.'),
  (104, 'typical-development', 'A 7-month-old repeats the same consonant-vowel syllable, as in ''bababa''. Which stage of prelinguistic development does this reflect?', 'Cooing with vowel-like sounds', 'Variegated babbling', 'Jargon with adult-like intonation', 'Canonical (reduplicated) babbling', 'D', 'Reduplicated babbling of repeated CV syllables typically emerges around 6 to 8 months. Variegated babbling mixes different syllables, and jargon adds adult-like intonation later in the first year.'),
  (105, 'fluency-treatment', 'In the Lidcombe Program for preschool children who stutter, who primarily delivers treatment?', 'The SLP, in daily individual clinic sessions', 'Preschool teachers, through daily classroom fluency drills', 'Parents, giving verbal contingencies in everyday conversation', 'The child, through self-monitoring with a feedback device', 'C', 'In Lidcombe, parents give verbal contingencies for stutter-free and stuttered speech during daily conversations, with weekly SLP visits to train and monitor. The SLP doesn''t deliver daily therapy directly.'),
  (106, 'anatomy-physiology', 'Which muscle mainly elevates the velum to achieve velopharyngeal closure?', 'Levator veli palatini', 'Tensor veli palatini', 'Palatoglossus', 'Superior longitudinal', 'A', 'The levator veli palatini lifts the velum up and back. The tensor veli palatini mainly opens the eustachian tube, and the palatoglossus lowers the velum.'),
  (107, 'aphasia-assessment', 'A patient has fluent speech, good auditory comprehension, and marked trouble repeating. He makes phonemic paraphasias and repeatedly tries to correct them, getting closer each time. Which aphasia type is most likely?', 'Wernicke''s aphasia', 'Conduction aphasia', 'Transcortical sensory aphasia', 'Global aphasia', 'B', 'Poor repetition with intact comprehension and self-correction attempts (conduite d''approche) is the hallmark of conduction aphasia. Wernicke''s aphasia includes poor comprehension and limited awareness.'),
  (108, 'child-language-treatment', 'A child says ''Doggie run.'' The adult replies, ''Yes, the doggie is running to his bowl because he''s hungry.'' Which technique did the adult use?', 'Expansion', 'Self-talk', 'Parallel talk', 'Extension', 'D', 'An extension adds new information to the child''s idea. An expansion restates the child''s words in a more complete adult form without adding new content, such as ''The doggie is running.'''),
  (109, 'dysphagia-assessment', 'An SLP suspects a patient has reduced hyolaryngeal excursion and reduced upper esophageal sphincter opening. Which assessment best evaluates these?', 'Fiberoptic endoscopic evaluation of swallowing', 'Clinical bedside swallow evaluation', 'Oral mechanism examination', 'Videofluoroscopic swallow study (MBSS)', 'D', 'Videofluoroscopy shows bony and structural movement across all phases, including hyoid movement and UES opening. FEES can''t directly view these events during the swallow.'),
  (110, 'ethics', 'Which task can a speech-language pathology assistant (SLPA) perform under ASHA guidance?', 'Conducting diagnostic evaluations of new clients', 'Writing and changing treatment goals', 'Deciding when a client should be discharged', 'Carrying out a treatment plan the SLP developed', 'D', 'SLPAs may implement treatment plans and collect data under supervision. Evaluating, interpreting results, writing goals, and discharge decisions stay with the SLP.'),
  (111, 'voice-treatment', 'Which statement best describes LSVT LOUD for a person with Parkinson''s disease?', 'Four sessions a week for four weeks, focused on loudness', 'Weekly sessions over 6 months focused on pitch range', 'Oral motor exercises to strengthen the lips and tongue', 'Training a softer, breathy voice to reduce strain', 'A', 'LSVT LOUD uses one target, loud voice with high effort, in 16 intensive sessions over 4 weeks. It recalibrates the person''s sense of how loud they sound.'),
  (112, 'autism-assessment', 'Which tool is a standardized, semi-structured observation used in diagnosing autism?', 'M-CHAT-R/F', 'ADOS-2', 'CELF-5', 'PPVT-5', 'B', 'The ADOS-2 uses planned activities to observe social communication and repetitive behaviors. The M-CHAT-R/F is a parent screener, and the CELF-5 and PPVT-5 measure language.'),
  (113, 'motor-speech-treatment', 'Which treatment for childhood apraxia of speech has children practice multisyllabic nonwords, such as ''BAgata'' and ''baGAta'', with changing stress patterns?', 'The Lidcombe Program', 'Melodic Intonation Therapy (MIT)', 'Hodson''s Cycles Phonological Approach', 'Rapid Syllable Transition Treatment (ReST)', 'D', 'ReST targets accurate sounds, smooth syllable transitions, and correct lexical stress with pseudowords. Lidcombe is for stuttering.'),
  (114, 'hearing', 'A tympanogram shows a normally shaped peak at significant negative pressure (Type C). What does this suggest?', 'Otosclerosis', 'Cochlear damage', 'Eustachian tube dysfunction', 'A perforated tympanic membrane', 'C', 'A Type C tracing shows negative middle ear pressure, typically from eustachian tube dysfunction. Otosclerosis usually gives a shallow Type As tracing.'),
  (115, 'child-language-assessment', 'Which type of assessment compares a child''s performance to a set standard of mastery rather than to same-age peers?', 'Criterion-referenced', 'Norm-referenced', 'Standardized with age equivalents', 'Percentile-based', 'A', 'Criterion-referenced measures, such as probes for a target skill, show whether a child meets a set criterion. Norm-referenced tests compare a child with a normative sample.'),
  (116, 'cognitive-treatment', 'A young adult with a TBI completes treatment tasks that move from sustained to selective, alternating, and divided attention. Which approach is this?', 'Spaced retrieval', 'Melodic intonation therapy', 'Attention Process Training', 'Semantic feature analysis', 'C', 'Attention Process Training uses a hierarchy of attention tasks based on a clinical model of attention. Spaced retrieval targets memory.'),
  (117, 'research-ebp', 'A test gives very similar scores when the same child takes it twice two weeks apart. What does this show?', 'Test-retest reliability', 'Content validity', 'Predictive validity', 'Specificity', 'A', 'Test-retest reliability is the stability of scores over time. Validity is whether the test measures what it claims to measure.'),
  (118, 'ssd-treatment', 'A highly unintelligible 4-year-old is treated with auditory bombardment and a set of phonological patterns, each targeted for a set time before moving on, regardless of accuracy. Which approach is this?', 'Traditional articulation therapy', 'Complexity approach', 'Core vocabulary approach', 'Cycles approach', 'D', 'The cycles approach (Hodson) cycles through patterns on a time basis rather than waiting for mastery, and includes auditory bombardment. It is designed for highly unintelligible children.'),
  (119, 'motor-speech-assessment', 'A patient with Parkinson''s disease has reduced loudness, monopitch, short rushes of speech, and repeats his own words and phrases. Which dysarthria type is this?', 'Hyperkinetic', 'Ataxic', 'Spastic', 'Hypokinetic', 'D', 'Basal ganglia control circuit damage in Parkinson''s disease causes hypokinetic dysarthria, including reduced loudness, rushes of speech, and palilalia. Hyperkinetic dysarthria involves involuntary extra movements.'),
  (120, 'dysphagia-treatment', 'A patient is taught to take a breath and hold it, swallow while holding it, then cough right after. Which maneuver is this?', 'Mendelsohn maneuver', 'Effortful swallow', 'Supraglottic swallow', 'Shaker exercise', 'C', 'The supraglottic swallow closes the vocal folds before and during the swallow, then clears any residue with a cough. It''s used for reduced or late vocal fold closure.'),
  (121, 'legislation', 'A student with a disability doesn''t qualify for special education under IDEA but needs classroom accommodations. Which law most likely provides them?', 'Section 504 of the Rehabilitation Act', 'FERPA (Family Educational Rights and Privacy Act)', 'HIPAA (Health Insurance Portability and Accountability Act)', 'IDEA Part C early intervention', 'A', 'Section 504 protects people with disabilities that substantially limit a major life activity, often through a 504 plan of accommodations. FERPA and HIPAA protect privacy.'),
  (122, 'fluency-assessment', 'During blocks, a 12-year-old blinks his eyes and jerks his head. What are these behaviors called?', 'Secondary (accessory) behaviors', 'Core stuttering behaviors', 'Typical disfluencies', 'Cluttering behaviors', 'A', 'Secondary behaviors are learned reactions used to escape or avoid stuttering. Core behaviors are the repetitions, prolongations, and blocks themselves.'),
  (123, 'aphasia-treatment', 'A woman with nonfluent aphasia practices a short personal monologue about her grandchildren until she can say it automatically in conversation. Which approach is this?', 'Semantic feature analysis', 'Treatment of underlying forms', 'Phonological components analysis', 'Script training', 'D', 'Script training uses repeated practice of personally relevant scripts to build automatic production in daily situations. It''s often used with nonfluent aphasia and apraxia of speech.'),
  (124, 'aac', 'Which is an example of unaided AAC?', 'A picture communication board', 'A speech-generating device', 'Manual signs and gestures', 'A letter board', 'C', 'Unaided AAC uses only the body, such as signs, gestures, and facial expressions. Aided AAC needs an external tool, from a picture board to a device.'),
  (125, 'voice-resonance-assessment', 'A 4-year-old has a progressively hoarse voice and noisy breathing. Laryngoscopy shows wart-like growths that keep coming back after removal. What is the most likely diagnosis?', 'Vocal fold nodules', 'Reinke''s edema', 'Recurrent respiratory papillomatosis', 'Paradoxical vocal fold motion', 'C', 'Papillomas are caused by HPV, often recur, and can block the airway, so they need medical management. Nodules don''t usually cause breathing problems.'),
  (126, 'cultural-linguistic', 'A 4-year-old who recently moved to the U.S. says almost nothing in English at preschool but talks freely at home in Mandarin. What is most likely?', 'Selective mutism requiring immediate treatment', 'A language disorder', 'Autism spectrum disorder', 'A typical silent period in second language learning', 'D', 'Many young second-language learners go through a silent period of listening before speaking the new language. Talking normally in the home language suggests typical development.'),
  (127, 'cognitive-assessment', 'After a right hemisphere stroke, a patient speaks fluently and names well, but his speech is flat in tone, he goes off topic, and he misses the point of jokes. What does this most likely reflect?', 'Wernicke''s aphasia from a temporal lesion', 'Broca''s aphasia from a frontal lesion', 'Spastic dysarthria from bilateral upper motor neuron damage', 'A right hemisphere cognitive-communication disorder', 'D', 'Right hemisphere damage often causes aprosodia, tangential discourse, and trouble with inference and humor, while basic language stays intact. Aphasia usually follows left hemisphere damage.'),
  (128, 'autism-treatment', 'An SLP writes a short, personalized story describing what happens at a haircut and how others might feel, to prepare a child for the visit. What is this called?', 'Video modeling', 'Pivotal Response Treatment', 'A Social Story', 'A visual schedule', 'C', 'Social Stories (Carol Gray) describe a situation, its cues, and others'' perspectives in a clear, positive way. Video modeling shows a model doing the behavior.'),
  (129, 'cleft-craniofacial', 'Which group of findings suggests a submucous cleft palate?', 'A visible open cleft running through both the hard and soft palate', 'A cleft of the lip only', 'Enlarged tonsils and adenoids', 'Bifid uvula, a bluish midline zone, and a notch in the hard palate', 'D', 'The classic triad of a submucous cleft is a bifid uvula, a zona pellucida, and a notch at the back of the hard palate. The cleft is hidden under the mucosa.'),
  (130, 'speech-science', 'In English, which stop typically has the longest positive voice onset time?', '/b/ in ''buy''', '/d/ in ''die''', '/g/ in ''guy''', '/pʰ/ in ''pie''', 'D', 'Voiceless aspirated stops have a long lag between release and voicing. Voiced stops have short-lag or negative VOT.'),
  (131, 'literacy', 'According to ASHA, what is the SLP''s role in reading and writing for children and adolescents?', 'SLPs address only spoken language, never reading', 'SLPs help prevent, identify, assess, and treat literacy problems', 'SLPs work on literacy only when a reading specialist isn''t available', 'SLPs teach handwriting only', 'B', 'ASHA''s position is that SLPs play a direct role in literacy, because spoken and written language are closely connected. They work with teachers and reading specialists.'),
  (132, 'counseling-collaboration', 'On an early intervention team, an SLP teaches the physical therapist to use language strategies during her sessions, and team members share roles across disciplines. Which team model is this?', 'Multidisciplinary', 'Transdisciplinary', 'Interdisciplinary', 'Intradisciplinary', 'B', 'Transdisciplinary teams use role release, where professionals teach and share skills across disciplines. Multidisciplinary teams work separately, and interdisciplinary teams coordinate but keep distinct roles.'),
  (133, 'neuroscience', 'A stroke patient has weakness of the lower right face but can still wrinkle both sides of his forehead. Where is the lesion most likely?', 'Lower motor neuron, right facial nerve', 'Lower motor neuron, left facial nerve', 'Right cerebellum', 'Upper motor neuron, left hemisphere', 'D', 'The upper face gets input from both hemispheres, so a UMN lesion spares the forehead and weakens the opposite lower face. A LMN facial nerve lesion weakens the whole same side of the face.'),
  (134, 'early-intervention-feeding', 'Around what postmenstrual age does a preterm infant typically begin to coordinate sucking, swallowing, and breathing well enough for oral feeding?', 'About 24 to 26 weeks', 'About 40 to 42 weeks', 'About 32 to 34 weeks', 'About 28 weeks', 'C', 'Suck-swallow-breathe coordination usually matures around 32 to 34 weeks postmenstrual age. Readiness also depends on the infant''s stability and cues, not age alone.'),
  (135, 'genetic-syndromes', 'A child is very sociable and has relatively strong expressive vocabulary, but has poor visuospatial skills, a heart condition, and sensitivity to loud sounds. Which syndrome is most likely?', 'Williams syndrome', 'Fragile X syndrome', 'Prader-Willi syndrome', 'Cri du chat syndrome', 'A', 'Williams syndrome (7q11.23 deletion) is known for strong sociability and relatively strong expressive language, with weak visuospatial skills, heart defects, and hyperacusis.'),
  (136, 'head-neck-laryngectomy', 'After a total laryngectomy, why is a heat and moisture exchanger (HME) placed over the stoma?', 'To let air enter through the mouth', 'To make the voice louder', 'To warm, humidify, and filter the air', 'To keep food from entering the stoma', 'C', 'Breathing through a stoma bypasses the nose, so air arrives dry and cold. An HME restores some conditioning, reducing mucus, coughing, and infections.'),
  (137, 'ssd-assessment', 'A connected speech sample from a 6-year-old yields a percentage of consonants correct (PCC) of 58 percent. Using Shriberg and Kwiatkowski''s severity ranges, how is this rated?', 'Mild', 'Mild-moderate', 'Moderate-severe', 'Severe', 'C', 'PCC above 85 percent is mild, 65 to 85 is mild-moderate, 50 to 65 is moderate-severe, and below 50 is severe. A PCC of 58 percent falls in the moderate-severe range.'),
  (138, 'typical-development', 'Typically developing children usually pass false-belief tasks, showing they understand someone else can hold a mistaken belief, around what age?', 'About 18 months', 'About 4 years', 'About 2 years', 'About 7 years', 'B', 'First-order theory of mind, measured by false-belief tasks, typically emerges around age 4. Its delay is often discussed in autism.'),
  (139, 'fluency-treatment', 'An SLP asks an adult who stutters to stutter on purpose while asking store clerks for directions. What is the main goal of this activity?', 'Eliminating all stuttering moments', 'Increasing speaking rate', 'Reducing fear and avoidance of stuttering', 'Practicing prolonged speech in public', 'C', 'Voluntary stuttering desensitizes the speaker and reduces fear, shame, and avoidance. It isn''t meant to increase fluency directly.'),
  (140, 'anatomy-physiology', 'During which phase of swallowing do the larynx elevate, the epiglottis invert, and the upper esophageal sphincter open?', 'Pharyngeal phase', 'Oral preparatory phase', 'Oral transit phase', 'Esophageal phase', 'A', 'These protective and transport events happen during the pharyngeal phase. In the oral phases the bolus is formed and moved back, and in the esophageal phase peristalsis carries it to the stomach.'),
  (141, 'aphasia-assessment', 'After a large left middle cerebral artery stroke, a patient has very limited speech output, poor comprehension, and can''t repeat or name. Which aphasia type fits?', 'Broca''s aphasia', 'Global aphasia', 'Mixed transcortical aphasia', 'Anomic aphasia', 'B', 'Severe deficits across expression, comprehension, repetition, and naming define global aphasia, usually after large perisylvian damage. Mixed transcortical aphasia spares repetition.'),
  (142, 'child-language-treatment', 'While a child builds a block tower, the SLP describes what the child is doing: ''You''re stacking. You put the red one on top.'' What is this technique called?', 'Self-talk', 'Recasting', 'Parallel talk', 'Focused stimulation', 'C', 'Parallel talk describes the child''s own actions as they happen. Self-talk describes the adult''s own actions.'),
  (143, 'dysphagia-assessment', 'What is the difference between laryngeal penetration and aspiration?', 'Penetration happens only with solids; aspiration only with liquids', 'Penetration is always silent; aspiration always causes a strong cough', 'Penetration enters the esophagus; aspiration enters the larynx', 'Penetration stays above the true vocal folds; aspiration passes below them', 'D', 'Penetration is material entering the laryngeal vestibule but staying above the true vocal folds. Aspiration is material passing below the folds into the trachea.'),
  (144, 'ethics', 'To earn the ASHA CCC-SLP, what clinical fellowship is required after graduate school?', 'At least 400 hours over 12 weeks, supervised by any licensed clinician', 'A one-year paid internship in any setting, with no minimum hours', 'Six months of supervised work with an ASHA-certified audiologist', 'At least 1,260 hours over a minimum of 36 weeks, mentored by a certified SLP', 'D', 'The clinical fellowship requires at least 1,260 hours and 36 weeks of full-time equivalent experience, mentored by an ASHA-certified SLP. The 400 hours describe graduate clinical practicum.'),
  (145, 'voice-treatment', 'Which program uses a warm-up sustained /i/, pitch glides up and down, and sustained notes, done twice a day?', 'Resonant voice therapy', 'Vocal function exercises', 'LSVT LOUD', 'Circumlaryngeal massage', 'B', 'Stemple''s vocal function exercises are four sustained-vowel and glide exercises done twice daily to balance respiration, phonation, and resonance. LSVT LOUD targets loudness alone.'),
  (146, 'autism-assessment', 'An autistic 4-year-old often repeats phrases from TV shows, such as ''Time to go, buddy!'' when he wants to leave. How should the SLP view these phrases during assessment?', 'As meaningless behaviors to be extinguished', 'As possibly communicative, so their functions should be analyzed', 'As a sign that the child fully understands every word in the phrases', 'As proof of intellectual disability', 'B', 'Delayed echolalia often serves functions such as requesting or protesting, so the SLP notes when and why it happens. It doesn''t mean the child knows each word in the phrase.'),
  (147, 'motor-speech-treatment', 'A parent asks whether blowing horns and tongue push-ups will help her child with childhood apraxia of speech. What is the best response?', 'Yes, strengthening exercises should come before speech practice', 'Yes, as long as the exercises are done daily at home', 'Only the blowing exercises help, not the tongue exercises', 'Evidence doesn''t support them; speech practice works better', 'D', 'Nonspeech oral motor exercises haven''t been shown to improve speech. Speech is best learned by practicing speech itself.'),
  (148, 'hearing', 'A child has a pure-tone average of 65 dB HL in both ears. Using common degree categories, how is this loss classified?', 'Moderately severe', 'Mild', 'Moderate', 'Profound', 'A', 'A common scale rates 26 to 40 dB HL as mild, 41 to 55 as moderate, 56 to 70 as moderately severe, 71 to 90 as severe, and above 90 as profound.'),
  (149, 'child-language-assessment', 'How many utterances are commonly recommended as a minimum for a representative spontaneous language sample?', '10 utterances', '20 utterances', '50 utterances', '500 utterances', 'C', 'A sample of at least 50 utterances (often 50 to 100) is a common guideline for reliable measures such as MLU. Very short samples aren''t representative.'),
  (150, 'cognitive-treatment', 'A client with executive function deficits after a TBI learns to stop, define the goal, list steps, do them, and check the result. Which approach is this?', 'Errorless learning of the steps of daily routines', 'Constraint-induced therapy to force use of speech', 'Visual scanning training with a margin anchor', 'Metacognitive strategy (goal management) training', 'D', 'Goal management training and similar metacognitive strategies teach self-regulation through planning and checking. They target executive function, not memory or neglect.'),
  (151, 'research-ebp', 'A panel of experts reviews a new aphasia test and confirms that its items cover all the important areas of language. What kind of evidence is this?', 'Content validity', 'Test-retest reliability', 'Interrater reliability', 'Sensitivity', 'A', 'Content validity is how well the items represent the full area being measured. Reliability is about the consistency of scores.'),
  (152, 'ssd-treatment', 'Which strategy is most consistent with the complexity approach to treating speech sound disorders?', 'Starting with the most stimulable, earliest-developing sounds', 'Targeting complex, later-developing sounds to spark wider change', 'Teaching sounds only in isolation', 'Treating one sound to mastery before introducing any others', 'B', 'The complexity approach picks complex targets, such as clusters and late-developing sounds, because learning them tends to generalize to simpler untreated sounds.'),
  (153, 'motor-speech-assessment', 'A patient with Huntington''s disease has speech marked by sudden, unpredictable variations in loudness, pitch, and articulation from involuntary movements. Which dysarthria type is this?', 'Hypokinetic', 'Flaccid', 'Hyperkinetic', 'Unilateral upper motor neuron', 'C', 'Involuntary movements, such as chorea, interrupt speech in hyperkinetic dysarthria, which comes from basal ganglia damage. Hypokinetic dysarthria involves reduced movement.'),
  (154, 'dysphagia-treatment', 'A patient is told to squeeze hard with all the throat muscles while swallowing. Which problem does this effortful swallow mainly address?', 'Reduced lip closure and anterior spillage', 'Reduced tongue base retraction and vallecular residue', 'Velopharyngeal insufficiency with nasal regurgitation', 'Reduced jaw opening during chewing', 'B', 'The effortful swallow increases tongue base retraction and pharyngeal pressure, reducing vallecular residue. It isn''t aimed at oral-phase problems such as lip closure.'),
  (155, 'legislation', 'Which law gives parents the right to review their child''s school records and protects the privacy of those records?', 'FERPA', 'HIPAA', 'ADA', 'Section 504', 'A', 'The Family Educational Rights and Privacy Act covers education records. HIPAA covers health information held by health care providers and health plans.'),
  (156, 'fluency-assessment', 'In a 300-syllable sample, 12 syllables are stuttered. What is the percentage of syllables stuttered?', '12 percent', '25 percent', '0.4 percent', '4 percent', 'D', 'Divide stuttered syllables by total syllables and multiply by 100: 12 divided by 300 equals 0.04, or 4 percent.'),
  (157, 'aphasia-treatment', 'In which treatment do the clinician and patient take turns sending new information, the patient may use any way of communicating, and feedback is based on whether the message was understood?', 'Constraint-induced language therapy (CILT)', 'Melodic intonation therapy (MIT)', 'Promoting Aphasics'' Communicative Effectiveness (PACE)', 'Verb network strengthening treatment (VNeST)', 'C', 'PACE follows natural conversation: equal roles, new information, free choice of modality, and natural feedback. CILT limits the patient to speech.'),
  (158, 'aac', 'For a beginning communicator, which type of symbol is generally the most transparent (easiest to recognize)?', 'Line drawings', 'Blissymbols', 'Printed words', 'Real objects', 'D', 'Real objects are the most iconic, followed by photos and then line drawings. Blissymbols and printed words are more abstract.'),
  (159, 'voice-resonance-assessment', 'A patient''s voice has sudden strained, effortful breaks during speech, but her voice is normal when laughing or singing. Which disorder is most likely?', 'Abductor spasmodic dysphonia', 'Vocal fold nodules', 'Unilateral vocal fold paralysis', 'Adductor spasmodic dysphonia', 'D', 'Adductor spasmodic dysphonia is a focal laryngeal dystonia with involuntary spasms that squeeze the folds closed, causing strained breaks. Abductor SD causes breathy breaks. It''s often treated with botulinum toxin.'),
  (160, 'cultural-linguistic', 'A bilingual child switches between Spanish and English within one sentence. How should the SLP interpret this?', 'As evidence of language confusion', 'As a sign of a language disorder', 'As a reason to stop using Spanish at home', 'As a normal, rule-governed bilingual behavior', 'D', 'Code-switching is normal and often reflects skill in both languages. It isn''t a sign of disorder or confusion.'),
  (161, 'cognitive-assessment', 'A 58-year-old shows early personality changes, disinhibition, and poor judgment, while memory is relatively spared. Which type of dementia is most likely?', 'Frontotemporal dementia', 'Alzheimer''s disease', 'Vascular dementia', 'Dementia with Lewy bodies', 'A', 'Behavioral variant frontotemporal dementia often begins with personality and behavior changes at a younger age. Alzheimer''s disease usually begins with episodic memory loss.'),
  (162, 'autism-treatment', 'Which goal for an autistic teenager is most consistent with neurodiversity-affirming practice?', 'Making eye contact for 5 seconds during conversations', 'Telling others what helps her communicate, such as needing breaks', 'Stopping all hand flapping in class', 'Using small talk scripts so that she appears less autistic', 'B', 'Affirming practice prioritizes self-advocacy and communication that matters to the person, rather than hiding harmless autistic traits. Forced eye contact and suppressing stimming can cause distress.'),
  (163, 'cleft-craniofacial', 'Why do children with cleft palate have a high rate of middle ear fluid and otitis media?', 'The tensor veli palatini doesn''t open the tube well', 'The cochlea is usually malformed at birth', 'The eardrum is often missing or thinned', 'The auditory nerve is damaged during palate surgery', 'A', 'The cleft disrupts the tensor veli palatini, which normally opens the eustachian tube. Many children need ear tubes and regular hearing checks.'),
  (164, 'speech-science', 'According to the source-filter theory of speech production, what are the source and the filter for vowels?', 'The lungs and the vocal folds', 'The tongue and the lips together', 'The vibrating vocal folds and the vocal tract', 'The nasal cavity and the vibrating larynx', 'C', 'The vocal folds produce the source sound, and the shape of the vocal tract filters it, creating formants. The lungs power the source.'),
  (165, 'literacy', 'How many phonemes are in the word ''box''?', '4', '3', '2', '1', 'A', '''Box'' is pronounced /bɑks/, so the letter x stands for two sounds, /k/ and /s/. Counting letters instead of sounds gives 3.'),
  (166, 'counseling-collaboration', 'Under ASHA requirements, what must an SLP have before supervising graduate students or clinical fellows?', 'A current state license, with no other requirement at all', 'At least 10 years of full-time clinical experience', '9 months post-CCC experience and 2 hours of supervision training', 'A doctoral degree in communication sciences and disorders', 'C', 'ASHA requires 9 months of full-time experience after earning the CCC and at least 2 hours of professional development in clinical supervision.'),
  (167, 'neuroscience', 'During an oral mechanism exam, a patient''s tongue deviates to the left when protruded, with atrophy on the left side. What does this suggest?', 'Damage to the right hypoglossal nerve', 'Damage to the left hypoglossal nerve', 'Damage to the left facial nerve', 'Damage to the right trigeminal nerve', 'B', 'With a lower motor neuron lesion of CN XII, the tongue deviates toward the weak side because the stronger side''s genioglossus pushes it over.'),
  (168, 'early-intervention-feeding', 'A 2019 consensus definition of pediatric feeding disorder describes impaired oral intake linked to dysfunction in which areas?', 'Speech, language, hearing, and voice', 'Motor, cognitive, vision, and hearing', 'Medical, nutritional, feeding skill, and psychosocial', 'Dental health, sleep, behavior, and growth only', 'C', 'Goday and colleagues defined pediatric feeding disorder across four domains: medical, nutritional, feeding skill, and psychosocial. Assessment and treatment are interdisciplinary.'),
  (169, 'genetic-syndromes', 'An infant with low muscle tone has a weak suck and needs feeding support. As a young child, she develops an intense, constant hunger. Which syndrome is most likely?', 'Prader-Willi syndrome', 'Williams syndrome', 'Down syndrome', 'Treacher Collins syndrome', 'A', 'Prader-Willi syndrome (missing paternal chromosome 15 genes) starts with hypotonia and poor feeding in infancy, then progresses to hyperphagia. Speech is often affected by hypotonia.'),
  (170, 'head-neck-laryngectomy', 'A patient with a TE voice prosthesis notices liquid coming out of his stoma when he drinks, from the center of the prosthesis. What does this suggest?', 'Normal function of the prosthesis that needs no action', 'The valve is leaking and likely needs replacement', 'He should switch to esophageal speech', 'His PE segment is too tight for speech', 'B', 'Leakage through the center of the prosthesis means the one-way valve isn''t sealing, often from wear or yeast growth. Leakage around the outside suggests a puncture problem.'),
  (171, 'ssd-assessment', 'A 7-year-old produces /s/ and /z/ with air escaping over the sides of the tongue in all word positions. All other sounds are produced correctly. Which diagnosis best fits?', 'A phonological disorder affecting fricatives', 'Childhood apraxia of speech', 'An articulation (phonetic) disorder', 'Flaccid dysarthria', 'C', 'A consistent distortion of one sound class with an otherwise intact system points to a motor-based articulation error, here a lateral lisp. A phonological disorder involves rule-based patterns that collapse contrasts across sound classes.'),
  (172, 'typical-development', 'A 3-year-old hears an unfamiliar color word once, used to name a tray, and the next day picks out that tray when asked for it. Which process does this illustrate?', 'Overextension', 'Fast mapping', 'Syntactic bootstrapping', 'Echolalia', 'B', 'Fast mapping is forming an initial link between a new word and its meaning after very brief exposure. Syntactic bootstrapping uses sentence structure, not a single exposure, to infer meaning.'),
  (173, 'fluency-treatment', 'A 15-year-old speaks very fast in irregular bursts, collapsing syllables, and seems unaware of it. Listeners often can''t follow him. Which treatment focus is most appropriate?', 'Cancellations after each stuttered word', 'Slowing rate and building self-monitoring with planned pauses', 'Desensitization to the fear of blocking on feared words', 'An airflow technique to prevent laryngeal blocks in speech', 'B', 'This profile suggests cluttering, which is treated by slowing rate, adding pauses, and building awareness. Cancellations and desensitization target stuttering behaviors and feelings.'),
  (174, 'anatomy-physiology', 'According to the myoelastic-aerodynamic theory, what brings the vocal folds back together after air pressure blows them apart?', 'A separate nerve impulse sent for each vibratory cycle', 'Tissue elasticity and the pressure drop from fast airflow', 'Active contraction of the posterior cricoarytenoid muscle', 'A further rise in subglottal air pressure', 'B', 'The folds'' elasticity and the Bernoulli effect draw them back together in each cycle. The idea of a nerve impulse per cycle is the discredited neurochronaxic theory, and rising subglottal pressure is what blows them apart.'),
  (175, 'aphasia-assessment', 'A patient''s speech is fluent and grammatical, and comprehension and repetition are good, but she often describes items she can''t name (''the thing you write with''). Which aphasia type is most likely?', 'Conduction aphasia', 'Transcortical sensory aphasia', 'Anomic aphasia', 'Wernicke''s aphasia', 'C', 'Word-finding trouble with circumlocution, and otherwise intact skills, defines anomic aphasia. Conduction aphasia would show poor repetition.'),
  (176, 'child-language-treatment', 'A 9-year-old with developmental language disorder tells stories as lists of events with no problem, attempts, or resolution. Which intervention approach is most appropriate?', 'Story grammar instruction with visual icons and retelling', 'Practicing articulation of long multisyllabic words', 'Drilling vocabulary definitions in isolation', 'Expanding the child''s two-word utterances', 'A', 'Narrative intervention that teaches story grammar parts with visual supports builds causal, goal-based stories. The other activities don''t target narrative structure.'),
  (177, 'dysphagia-assessment', 'During a clinical swallow evaluation, a patient''s voice sounds wet and gurgly right after sips of water. What does this most likely suggest?', 'The patient has normal pharyngeal clearance', 'The patient has a reduced gag reflex and nothing more', 'Material may be in or near the laryngeal vestibule', 'The oral phase of the swallow is prolonged', 'C', 'A wet vocal quality after swallows is a clinical sign that material may be pooling near or entering the larynx. It calls for further assessment.'),
  (178, 'ethics', 'How many certification maintenance hours must an ASHA-certified SLP earn in each 3-year interval?', '10 hours, with no specific topics required', '60 hours, including 10 hours in ethics', 'No hours, as long as the SLP holds a state license', '30 hours, including at least 1 hour in ethics', 'D', 'ASHA requires 30 certification maintenance hours every 3 years, with at least 1 hour in ethics. A state license has its own separate requirements.'),
  (179, 'voice-treatment', 'A patient has a breathy voice from a unilateral left vocal fold paralysis. Which postural technique may improve glottal closure during therapy?', 'Tilting the head back and looking up', 'Turning the head toward the left (weaker) side', 'Turning the head toward the right (stronger) side', 'Lying flat on the back', 'B', 'Turning the head toward the paralyzed side can narrow that side of the glottis and improve closure. Head tilt back tends to open the airway rather than help closure.'),
  (180, 'autism-assessment', 'An 8-year-old has trouble with conversational turn-taking, adjusting language to listeners, and understanding implied meaning. He has no restricted or repetitive behaviors or interests. Which diagnosis is most consistent?', 'Autism spectrum disorder, requiring support', 'Social (pragmatic) communication disorder', 'Childhood apraxia of speech', 'Selective mutism in school settings', 'B', 'Social communication disorder involves pragmatic deficits without the restricted, repetitive behaviors needed for an autism diagnosis. Selective mutism involves not speaking in specific settings.'),
  (181, 'motor-speech-treatment', 'A man with Parkinson''s disease has hypokinetic dysarthria with short rushes of speech at a fast rate. Which tool can help him slow his rate?', 'A pacing board', 'A palatal lift', 'An electrolarynx', 'A speaking valve', 'A', 'A pacing board has the speaker tap a slot for each syllable or word, slowing rate and improving intelligibility. A palatal lift treats velopharyngeal weakness.'),
  (182, 'hearing', 'A factory worker''s audiogram shows a dip in thresholds around 4000 Hz with better hearing at 8000 Hz. What is the most likely cause?', 'Noise exposure', 'Middle ear fluid', 'Otosclerosis', 'Earwax blockage', 'A', 'A notch near 4000 Hz with recovery at 8000 Hz is the classic pattern of noise-induced hearing loss. Middle ear problems cause conductive loss with an air-bone gap.'),
  (183, 'child-language-assessment', 'A language sample contains 100 total words, of which 40 are different words. What is the type-token ratio?', '0.60', '2.50', '1.40', '0.40', 'D', 'The type-token ratio is different words (types) divided by total words (tokens), so 40 divided by 100 is 0.40.'),
  (184, 'cognitive-treatment', 'A patient with right hemisphere damage reads only the right side of each line of text. Which strategy is most appropriate?', 'Visual scanning training with a line on the left margin', 'Covering the left side of each page', 'Placing all objects and visitors on the patient''s right side', 'Teaching the patient to read each line faster', 'A', 'Left neglect is treated by training scanning to the left with an anchor, such as a colored line along the left margin. Keeping everything on the right avoids the problem instead of treating it.'),
  (185, 'research-ebp', 'What does a test''s sensitivity describe?', 'The proportion of people without the disorder who are correctly identified', 'The proportion of people with the disorder who are correctly identified', 'How stable scores are over time', 'How well two examiners agree', 'B', 'Sensitivity is the true positive rate. The true negative rate (people without the disorder correctly identified) is specificity.'),
  (186, 'ssd-treatment', 'Which sequence describes traditional articulation therapy (Van Riper)?', 'Conversation first, then sentences, words, and isolation', 'Isolation, syllables, words, phrases, sentences, conversation', 'Phonological patterns taught in timed cycles', 'Minimal pairs first, then maximal oppositions', 'B', 'Traditional therapy teaches one sound at a time, moving from isolation through gradually longer units to conversation. It often begins with ear training.'),
  (187, 'motor-speech-assessment', 'A patient with a single left-hemisphere stroke has mild, imprecise consonants and slight slowness, with weakness of the lower right face and tongue. Which dysarthria type is most likely?', 'Unilateral upper motor neuron', 'Flaccid', 'Ataxic', 'Mixed flaccid-spastic', 'A', 'Unilateral UMN dysarthria is usually mild and follows a one-sided stroke, with contralateral lower face and tongue weakness. Mixed flaccid-spastic dysarthria suggests ALS.'),
  (188, 'dysphagia-treatment', 'A patient lies flat and repeatedly raises his head to look at his toes without lifting his shoulders. What is the main goal of this Shaker exercise?', 'Strengthening the lips for better bolus control', 'Improving vocal fold closure during the swallow', 'Reducing tongue thrust during the oral phase of swallowing', 'Strengthening suprahyoid muscles to improve UES opening', 'D', 'The Shaker (head lift) exercise strengthens suprahyoid muscles that pull the larynx up and forward, which helps open the UES. Studies have shown wider UES opening and less aspiration after the swallow.'),
  (189, 'legislation', 'An SLP in a hospital wants to discuss a patient''s care with a colleague. Which law governs how she protects the patient''s health information?', 'FERPA', 'IDEA', 'HIPAA', 'Section 504', 'C', 'HIPAA sets rules for protected health information in health care settings, including sharing only what''s necessary. FERPA covers school records.'),
  (190, 'fluency-assessment', 'What does the Stuttering Severity Instrument (SSI-4) measure?', 'The speaker''s attitudes toward communicating', 'Frequency, duration, and physical concomitants of stuttering', 'The effect of stuttering on the speaker''s quality of life', 'Speech sound accuracy in conversation', 'B', 'The SSI-4 rates frequency, the duration of the longest stutters, and physical concomitants, along with naturalness. Attitudes and quality of life need other tools.'),
  (191, 'aphasia-treatment', 'An SLP trains a husband to use gestures, written key words, and yes/no checks so his wife with aphasia can join conversations. Which approach is this?', 'Supported Conversation for Adults with Aphasia', 'Treatment of underlying forms', 'Constraint-induced language therapy (CILT)', 'Phonological components analysis', 'A', 'Supported conversation (Kagan) trains partners to reveal the person''s competence by supporting both understanding and expression. It targets the partner rather than the person''s language skills.'),
  (192, 'aac', 'Compared with scanning, why is direct selection usually preferred when a person can use it?', 'It requires a switch and a scanning array', 'It is generally faster and less demanding', 'It works only on low-tech boards', 'It needs no motor control at all', 'B', 'Direct selection (pointing, touch, eye gaze) lets the user pick items immediately, while scanning waits for items to be offered. Scanning is used when direct selection isn''t reliable.'),
  (193, 'voice-resonance-assessment', 'What does the CAPE-V measure?', 'Vocal fold vibration as seen on stroboscopy', 'Airflow through the nose during speech', 'The effect of a voice disorder on the person''s daily life', 'Perceived voice quality, such as roughness and strain', 'D', 'The Consensus Auditory-Perceptual Evaluation of Voice rates overall severity, roughness, breathiness, strain, pitch, and loudness. The Voice Handicap Index measures daily-life impact.'),
  (194, 'cultural-linguistic', 'According to Cummins, about how long does it typically take an English learner to develop academic language (CALP) compared with social language (BICS)?', 'About 6 months for both', 'About 2 years for CALP, compared with 5 to 7 years for BICS', 'About 5 to 7 years for CALP, compared with about 2 years for BICS', 'Both develop in about a year', 'C', 'Conversational language comes faster than the academic language needed for school. Fluent social English doesn''t mean a student has academic English yet.'),
  (195, 'cognitive-assessment', 'A patient has fluctuating alertness, detailed visual hallucinations, and parkinsonian movements along with cognitive decline. Which type of dementia is most likely?', 'Dementia with Lewy bodies', 'Alzheimer''s disease', 'Frontotemporal dementia', 'Vascular dementia', 'A', 'Fluctuating cognition, visual hallucinations, and parkinsonism are core features of dementia with Lewy bodies. They aren''t typical early in Alzheimer''s disease.'),
  (196, 'autism-treatment', 'An autistic child watches short videos of a peer greeting classmates and asking to join a game, then practices the same actions. What is this approach called?', 'A Social Story', 'Video modeling', 'Facilitated communication', 'Errorless learning', 'B', 'Video modeling shows a target behavior on video for the child to imitate, and it has strong research support for teaching social and communication skills.'),
  (197, 'cleft-craniofacial', 'A newborn has a small lower jaw, a tongue that falls back into the throat, and a U-shaped cleft palate, with breathing problems. What is this?', 'Down syndrome', 'Treacher Collins syndrome', 'Velocardiofacial syndrome', 'Pierre Robin sequence', 'D', 'Pierre Robin sequence is micrognathia, glossoptosis, and airway obstruction, often with a U-shaped cleft palate. It can occur alone or as part of a syndrome.'),
  (198, 'speech-science', 'The sounds /s/ and /ʃ/ are both voiceless fricatives. Which feature differs between them?', 'Voicing', 'Manner of articulation', 'Place of articulation', 'Nasality', 'C', '/s/ is alveolar and /ʃ/ is postalveolar, so they differ only in place. Both are voiceless, oral fricatives.'),
  (199, 'literacy', 'A second grader now recognizes words instantly after decoding them a few times. Which process explains how these sight words are stored?', 'Memorizing the visual shape of each word', 'Guessing words from pictures', 'Learning words only through context', 'Orthographic mapping of letters to sounds', 'D', 'Orthographic mapping links a word''s spelling to its pronunciation, which requires phonemic awareness and letter-sound knowledge. Readers don''t store words as visual shapes.'),
  (200, 'counseling-collaboration', 'An SLP and a 2nd grade teacher plan and teach a vocabulary lesson together in the classroom for all students. What service model is this?', 'Pull-out therapy in the speech room', 'Consultation with the teacher only', 'A self-contained special education classroom', 'Co-teaching (classroom-based collaboration)', 'D', 'In co-teaching, the SLP and teacher share planning and instruction in the general classroom. It supports generalization and access to the curriculum.'),
  (201, 'neuroscience', 'Parkinson''s disease mainly involves loss of dopamine-producing neurons in which structure?', 'Cerebellum', 'Hippocampus', 'Broca''s area', 'Substantia nigra', 'D', 'Loss of dopamine neurons in the substantia nigra disrupts basal ganglia circuits, causing tremor, rigidity, slowness, and hypokinetic dysarthria.'),
  (202, 'early-intervention-feeding', 'Which practice best describes responsive feeding for a toddler?', 'Requiring the child to finish everything on the plate', 'Using dessert as a reward for eating vegetables', 'Following the child''s hunger and fullness cues without pressure', 'Distracting the child with screens so more bites get in at meals', 'C', 'Responsive feeding means caregivers decide what is offered while the child decides how much to eat, guided by their own cues. Pressure and rewards tend to increase food refusal.'),
  (203, 'genetic-syndromes', 'A child has severe speech impairment with few or no words, frequent smiling and laughter, seizures, and an unsteady gait. Which syndrome is most likely?', 'Williams syndrome', 'Angelman syndrome', 'Fragile X syndrome', '22q11.2 deletion syndrome', 'B', 'Angelman syndrome (loss of the maternal UBE3A gene on chromosome 15) causes minimal speech, a happy demeanor, seizures, and ataxia. AAC is a key part of intervention.'),
  (204, 'head-neck-laryngectomy', 'Before placing a one-way speaking valve on a patient''s tracheostomy tube, what must be done?', 'Fully deflate the cuff so air can reach the larynx', 'Fully inflate the cuff to protect the airway', 'Remove the tracheostomy tube completely', 'Cover the tube opening with a finger all day', 'A', 'A speaking valve lets air in through the trach and directs it out through the vocal folds. With the cuff inflated the patient can''t exhale and could suffocate.'),
  (205, 'ssd-assessment', 'A 2;6 child has very few words and limited sounds. The SLP wants to describe the sounds and syllable shapes the child uses without comparing them to adult targets. Which analysis fits this goal?', 'Relational analysis', 'Percentage of consonants correct', 'Independent analysis', 'A standardized single-word articulation test', 'C', 'An independent analysis describes the child''s own phonetic inventory and syllable shapes, which suits young or very unintelligible children. Relational analysis compares productions with adult targets.'),
  (206, 'typical-development', 'A toddler calls every four-legged animal ''doggie''. What is this called?', 'Underextension', 'Fast mapping', 'Circumlocution', 'Overextension', 'D', 'Overextension is applying a word to a broader category than the adult meaning. Underextension is the opposite, such as using ''dog'' only for the family pet.'),
  (207, 'fluency-treatment', 'In a Demands and Capacities approach such as RESTART-DCM for a preschooler who stutters, what do parents learn to do?', 'Praise every stutter-free utterance and correct stutters', 'Ask the child to repeat stuttered words smoothly', 'Teach the child to use voluntary stuttering', 'Lower demands, for example by slowing their own speech', 'D', 'Demands and Capacities treatment reduces environmental demands (such as fast parent speech and time pressure) while building the child''s capacities. Praise and correction of stutters are Lidcombe contingencies.'),
  (208, 'anatomy-physiology', 'The vocal folds attach anteriorly to the inner surface of which cartilage?', 'Thyroid', 'Cricoid', 'Epiglottis', 'Corniculate', 'A', 'The folds run from the inner angle of the thyroid cartilage in front to the vocal processes of the arytenoids in back. The arytenoids sit on the cricoid.'),
  (209, 'aphasia-assessment', 'A patient speaks fluently with semantic paraphasias and has poor auditory comprehension, yet repeats long sentences accurately and sometimes echoes the examiner. Which aphasia type fits?', 'Wernicke''s aphasia', 'Conduction aphasia', 'Transcortical sensory aphasia', 'Transcortical motor aphasia', 'C', 'Transcortical sensory aphasia resembles Wernicke''s aphasia but with preserved repetition, often with echolalia. Wernicke''s aphasia includes poor repetition.'),
  (210, 'child-language-treatment', 'Which annual goal is written in measurable terms?', 'The student will improve expressive grammar skills across all school settings this year', 'The student will understand and use verb tenses better during classroom lessons', 'Given picture scenes, the student will use subject-verb agreement in 8 of 10 sentences', 'The student will participate more often and more fully in classroom discussions', 'C', 'A measurable goal names the behavior, the conditions, and a criterion. The other options are vague and can''t be reliably measured.'),
  (211, 'dysphagia-assessment', 'Videofluoroscopy shows residue mainly in the valleculae after swallows. Which deficit does this most often suggest?', 'Reduced upper esophageal sphincter opening', 'Reduced lip closure', 'Reduced tongue base retraction', 'Delayed esophageal peristalsis', 'C', 'Vallecular residue is commonly linked to reduced tongue base retraction and reduced epiglottic inversion. Pyriform sinus residue points more to UES or pharyngeal constriction problems.'),
  (212, 'ethics', 'Which activity falls within the scope of practice for speech-language pathologists?', 'Pure-tone hearing screening', 'Diagnostic audiological evaluation', 'Fitting and dispensing hearing aids', 'Prescribing medication for reflux', 'A', 'SLPs may screen hearing, but diagnostic audiology and hearing aid fitting belong to audiologists. Prescribing medication is outside both professions'' scope.'),
  (213, 'voice-treatment', 'A 40-year-old has a strained, effortful voice with a high-held larynx and tight neck muscles, and a normal laryngeal exam other than tension. Which technique is most appropriate?', 'Hard glottal attacks to strengthen vocal fold closure', 'Pushing exercises with effortful voicing', 'Circumlaryngeal massage to lower and relax the larynx', 'Increasing loudness with LSVT LOUD', 'C', 'This is primary muscle tension dysphonia, and manual circumlaryngeal techniques reduce excess tension and lower the larynx. Hard attacks and pushing add more tension.'),
  (214, 'autism-assessment', 'A 2-year-old looks where an adult points but never brings toys to show or points to share interest. Which skill is most affected?', 'Responding to joint attention', 'Receptive vocabulary', 'Initiating joint attention', 'Motor imitation', 'C', 'Following another''s point shows responding to joint attention. Showing and pointing to share interest are ways of initiating it, which is often harder for autistic children.'),
  (215, 'motor-speech-treatment', 'A patient with flaccid dysarthria has severe hypernasality and nasal emission because his velum barely moves. Which treatment is most appropriate to discuss with the team?', 'Blowing exercises to strengthen the velum', 'Vocal function exercises', 'Delayed auditory feedback', 'A palatal lift prosthesis', 'D', 'A palatal lift raises a weak but mobile-enough velum to reduce hypernasality. Blowing exercises don''t improve velopharyngeal function for speech.'),
  (216, 'hearing', 'A 78-year-old says he hears people talking but can''t understand them, especially in noisy restaurants. What pattern does his audiogram most likely show?', 'Unilateral low-frequency conductive loss', 'A flat, mild conductive loss in both ears', 'Bilateral, sloping high-frequency sensorineural loss', 'Normal hearing with a Type B tympanogram in each ear', 'C', 'Presbycusis typically causes symmetrical high-frequency sensorineural loss. High-frequency consonants such as /s/, /f/, and /θ/ become hard to hear, which makes speech unclear.'),
  (217, 'child-language-assessment', 'Which finding is considered one of the strongest clinical markers of developmental language disorder in English-speaking children?', 'Frequent stuttering-like disfluencies in speech', 'Trouble marking tense, such as third person -s and -ed', 'Errors on later-developing sounds such as /r/ and /θ/', 'A receptive vocabulary well above age level', 'B', 'Weak tense and agreement marking (finite verb morphology), along with poor nonword repetition, is a well-studied marker of DLD. Speech sound and fluency errors point to other disorders.'),
  (218, 'cognitive-treatment', 'A patient with a TBI is at Rancho Los Amigos Level IV (confused, agitated). What is the most appropriate SLP approach?', 'Reduce stimulation and keep a calm, consistent routine', 'Begin intensive higher-level reasoning tasks', 'Train community outings such as shopping', 'Give a full standardized language battery right away', 'A', 'At Level IV, the patient is agitated and can''t process much information. The goal is a calm, consistent environment; complex tasks and testing aren''t appropriate yet.'),
  (219, 'research-ebp', 'A language screener correctly passes 95 of 100 children who don''t have a language disorder. What does this describe?', 'Sensitivity of 95 percent', 'Reliability of 95 percent', 'Specificity of 95 percent', 'A false positive rate of 95 percent', 'C', 'Specificity is the proportion of people without the disorder who test negative. Here the false positive rate is 5 percent.'),
  (220, 'ssd-treatment', 'An 8-year-old has a residual /r/ distortion that hasn''t improved with traditional therapy. Which approach has growing research support?', 'Nonspeech oral motor exercises', 'Auditory bombardment alone', 'Visual biofeedback, such as ultrasound', 'Waiting another year to see if it resolves', 'C', 'Ultrasound and other visual biofeedback show the tongue''s position, and studies support them for residual errors that resist traditional therapy. Nonspeech exercises aren''t supported.'),
  (221, 'motor-speech-assessment', 'Which disease is most often linked to a mixed flaccid-spastic dysarthria?', 'Parkinson''s disease', 'Huntington''s disease', 'Cerebellar degeneration', 'Amyotrophic lateral sclerosis', 'D', 'ALS damages both upper and lower motor neurons, so it causes features of both spastic and flaccid dysarthria. Parkinson''s disease causes hypokinetic dysarthria.'),
  (222, 'dysphagia-treatment', 'In the Masako (tongue-hold) maneuver, the patient swallows saliva with the tongue held between the teeth. Which instruction is important?', 'Use it with every bite of food at meals', 'Do it only while drinking thin liquids', 'Use it only as an exercise without food or liquid', 'Combine it with a head tilt back during meals', 'C', 'The tongue hold strengthens pharyngeal wall movement but reduces airway protection, so it''s an exercise only and isn''t used during meals.'),
  (223, 'legislation', 'Which law is a broad civil rights law that bans disability discrimination in employment, public services, and public places?', 'IDEA (Individuals with Disabilities Education Act)', 'FERPA', 'Americans with Disabilities Act (ADA)', 'Every Student Succeeds Act', 'C', 'The ADA protects people with disabilities from discrimination in jobs, public services, and public accommodations. IDEA governs special education.'),
  (224, 'fluency-assessment', 'An SLP wants to measure how stuttering affects an adult''s reactions, communication in daily life, and quality of life. Which tool fits best?', 'Overall Assessment of the Speaker''s Experience of Stuttering (OASES)', 'The Stuttering Severity Instrument, Fourth Edition (SSI-4)', 'The Goldman-Fristoe Test of Articulation (GFTA-3)', 'The Western Aphasia Battery-Revised (WAB-R)', 'A', 'The OASES measures the broader impact of stuttering beyond observable disfluencies. The SSI-4 measures observable severity.'),
  (225, 'aphasia-treatment', 'In which treatment for nonfluent aphasia does the SLP accept the patient''s description of a picture, then use wh-questions to help expand it?', 'Response elaboration training', 'Melodic intonation therapy', 'Semantic feature analysis', 'Script training', 'A', 'Response elaboration training is a loose training approach that shapes and expands the patient''s own responses. It doesn''t use a fixed target word.'),
  (226, 'aac', 'While talking with a child who uses AAC, a teacher points to symbols on the child''s device as she speaks key words. What is this called?', 'Unaided AAC', 'Aided language modeling', 'Feature matching', 'Partner-assisted scanning', 'B', 'Aided language modeling (or aided language stimulation) shows the child how to use the system in real communication. Children learn AAC by seeing others use it.'),
  (227, 'voice-resonance-assessment', 'In acoustic voice analysis, what does jitter measure?', 'Cycle-to-cycle variation in amplitude', 'Average fundamental frequency', 'The ratio of harmonics to noise', 'Cycle-to-cycle variation in frequency', 'D', 'Jitter is frequency perturbation, and shimmer is amplitude perturbation. Both tend to rise with irregular vocal fold vibration.'),
  (228, 'cultural-linguistic', 'An SLP needs an interpreter to evaluate a child whose family speaks Vietnamese. What is the best practice?', 'Use a trained interpreter, with briefing and debriefing', 'Have the child''s 10-year-old sibling interpret', 'Translate the English test word for word', 'Skip the family interview to save time and avoid confusion', 'A', 'Trained interpreters, with briefing, interaction, and debriefing steps, give the most accurate results. Family members, especially children, may add bias and face role conflicts.'),
  (229, 'cognitive-assessment', 'Which language change is most common in the early stage of Alzheimer''s disease?', 'Severe trouble repeating words', 'Loss of grammar, with short telegraphic sentences', 'Loss of the ability to read words aloud', 'Word-finding problems and vague, empty speech', 'D', 'Early Alzheimer''s disease commonly causes anomia and empty speech, while grammar, repetition, and reading aloud stay largely intact until later stages.'),
  (230, 'autism-treatment', 'Which intervention targets joint attention, symbolic play, engagement, and regulation in young autistic children?', 'PECS', 'Lidcombe Program', 'Melodic intonation therapy', 'JASPER', 'D', 'JASPER (Joint Attention, Symbolic Play, Engagement, and Regulation) is a play-based NDBI. PECS teaches picture-based requesting.'),
  (231, 'cleft-craniofacial', 'An SLP and surgeon want to see velopharyngeal closure directly during speech to plan treatment for VPI. Which assessment fits best?', 'Nasopharyngoscopy', 'Pure-tone audiometry', 'A modified barium swallow of solids', 'Tympanometry', 'A', 'Nasopharyngoscopy (or multiview videofluoroscopy) shows the size and location of the velopharyngeal gap during speech. Audiometry and tympanometry assess hearing.'),
  (232, 'speech-science', 'Which is the correct IPA transcription of the word ''thing''?', '/ðɪŋ/', '/θɪŋ/', '/θɪng/', '/tɪŋ/', 'B', '''Thing'' starts with the voiceless interdental fricative /θ/ and ends with the velar nasal /ŋ/. /ð/ is voiced, as in ''this''.'),
  (233, 'literacy', 'An autistic 6-year-old reads far above grade level but understands very little of what he reads. Which term describes this profile?', 'Hyperlexia', 'Dyslexia', 'Dysgraphia', 'Alexia', 'A', 'Hyperlexia is advanced decoding with comprehension well below it. It''s often seen in autism. Dyslexia is the opposite pattern, with poor decoding.'),
  (234, 'counseling-collaboration', 'A family believes their child''s speech delay is God''s plan and shouldn''t be treated. What is the most appropriate first step?', 'Tell them their belief is mistaken and therapy is needed', 'Report the family to child protective services right away', 'Ask about their beliefs and goals, and explain options respectfully', 'Refuse to discuss the child''s needs any further', 'C', 'Culturally responsive practice means learning about the family''s beliefs, respecting their decisions, and sharing information so they can choose. A different view of disability isn''t neglect.'),
  (235, 'neuroscience', 'Why does damage to the motor pathway in one hemisphere usually cause only mild speech problems?', 'Speech muscles have no upper motor neuron input', 'The cerebellum takes over all motor control', 'Most speech cranial nerve nuclei get input from both sides', 'Speech is controlled only by the right hemisphere''s motor cortex', 'C', 'Most speech-related cranial nerve nuclei get bilateral corticobulbar input. The lower face and, to some extent, the tongue are exceptions, which is why unilateral UMN dysarthria affects them.'),
  (236, 'early-intervention-feeding', 'Around what age do most infants show readiness to begin solid foods, such as sitting with support and good head control?', 'About 2 months', 'About 12 months', 'About 6 months', 'About 18 months', 'C', 'Most infants are ready for solids around 6 months, when they can sit with support, control their head, and show interest in food.'),
  (237, 'genetic-syndromes', 'A child has underdeveloped cheekbones and jaw, malformed outer ears, and conductive hearing loss, with typical intelligence. Which syndrome is most likely?', 'Treacher Collins syndrome', 'Down syndrome', 'Angelman syndrome', 'Prader-Willi syndrome', 'A', 'Treacher Collins syndrome affects facial bone development and often causes conductive hearing loss from outer and middle ear malformations. Cognition is usually typical.'),
  (238, 'head-neck-laryngectomy', 'A patient is starting radiation therapy for head and neck cancer. Why does the SLP teach swallowing exercises before and during treatment?', 'Because radiation has no effect on swallowing', 'To replace the need for any later follow-up visits', 'To speed up the course of radiation treatment', 'To keep muscles moving and reduce lasting dysphagia', 'D', 'Radiation can cause fibrosis, dry mouth, and trismus that lead to lasting dysphagia. Preventive exercises and continued eating by mouth are linked to better swallowing outcomes.'),
  (239, 'ssd-assessment', 'A 4-year-old says [tɪ] for ''key'' and [dʌn] for ''gun'', and produces /t/ and /d/ correctly. Which phonological process is shown?', 'Stopping', 'Velar fronting', 'Backing', 'Prevocalic voicing', 'B', 'Velar fronting replaces velars /k, g/ with alveolars /t, d/. Backing is the reverse, and stopping replaces fricatives or affricates with stops.'),
  (240, 'typical-development', 'An SLP gives a child just enough support to complete a task the child can''t yet do alone, then gradually fades that support. Which theoretical concept does this reflect?', 'Skinner''s operant conditioning', 'Chomsky''s language acquisition device', 'Piaget''s sensorimotor stage', 'Vygotsky''s zone of proximal development', 'D', 'The zone of proximal development is the gap between what a child can do alone and with guidance, and scaffolding works within it. Operant conditioning relies on reinforcement rather than graded support.'),
  (241, 'fluency-treatment', 'An adult is fluent in the clinic using new techniques but not at work. Which step best supports carryover?', 'Increasing the number of clinic sessions each week', 'Switching to a different treatment approach', 'Practicing in real situations, from easier to harder', 'Avoiding feared speaking situations until fluency is stable', 'C', 'Transfer is built by moving through a hierarchy of real situations from easier to harder. Avoiding feared situations tends to strengthen fear and avoidance.'),
  (242, 'anatomy-physiology', 'Which muscle group elevates the hyoid bone and larynx during swallowing?', 'Infrahyoid muscles', 'Suprahyoid muscles', 'Intrinsic laryngeal muscles', 'Muscles of mastication', 'B', 'Suprahyoid muscles such as the mylohyoid, geniohyoid, and digastric pull the hyoid up and forward. Infrahyoid muscles such as the sternohyoid lower it.'),
  (243, 'aphasia-assessment', 'A patient with aphasia names a picture of a spoon as ''fork''. What type of error is this?', 'Phonemic (literal) paraphasia', 'Neologism', 'Perseveration', 'Semantic (verbal) paraphasia', 'D', 'A real word related in meaning to the target is a semantic paraphasia. A phonemic paraphasia changes sounds within the word, as in ''spoom'' for ''spoon''.'),
  (244, 'child-language-treatment', 'An SLP is choosing vocabulary to teach a 4th grader with language disorder to support academic success. Which type of word is generally the best target?', 'Tier 1 everyday words, such as ''dog'' and ''happy''', 'Tier 3 rare words, such as ''isotope'', from one subject', 'Tier 2 words, such as ''analyze'', used across subjects', 'Words picked in alphabetical order from a dictionary', 'C', 'Tier 2 words are high-utility academic words used across contexts, so teaching them has wide payoff. Tier 1 words are usually learned through conversation, and Tier 3 words are taught within a subject.'),
  (245, 'dysphagia-assessment', 'On videofluoroscopy, thin liquid reaches the pyriform sinuses before the pharyngeal swallow begins. Which problem does this show?', 'Delayed initiation of the pharyngeal swallow', 'Reduced lingual strength in the oral phase', 'Cricopharyngeal achalasia', 'Normal swallow timing', 'A', 'When the bolus head reaches the pyriform sinuses before the swallow triggers, initiation is delayed, raising the risk of aspiration before the swallow. Normally the swallow triggers as the bolus passes the ramus of the mandible.'),
  (246, 'ethics', 'An AAC device company offers an SLP a commission for each of its devices she recommends. What should she do?', 'Decline, since it''s a conflict of interest that could bias recommendations', 'Accept the commission, as long as she discloses it to the families', 'Accept, because the company makes high-quality devices', 'Recommend only that company''s devices from now on', 'A', 'Accepting payment tied to recommendations is a conflict of interest that compromises professional judgment. Device choices must be based on the client''s needs.'),
  (247, 'voice-treatment', 'A 16-year-old male speaks with a high-pitched falsetto voice, but his larynx has matured normally. Which approach is most often effective?', 'Teaching a whispered voice to use until the pitch drops', 'Practicing upward pitch glides to stretch the vocal folds', 'Finding a lower pitch from a cough, then shaping it into speech', 'Referring for surgery to shorten the vocal folds', 'C', 'Mutational falsetto (puberphonia) often resolves quickly when the speaker finds his natural lower pitch through vegetative sounds or gentle pressure on the thyroid cartilage. Surgery isn''t indicated.'),
  (248, 'autism-assessment', 'What are DSM-5 severity levels for autism based on?', 'IQ score', 'The level of support the person needs', 'The number of words the person uses', 'Age at diagnosis', 'B', 'Severity is rated separately for each domain as requiring support, substantial support, or very substantial support. IQ and language level are noted with specifiers.'),
  (249, 'motor-speech-treatment', 'A woman with ataxic dysarthria after a cerebellar stroke has irregular articulatory breakdowns and excess, equal stress. Which treatment focus is most appropriate?', 'Increasing loudness with high effort', 'Strengthening the lips with resistance exercises', 'Slowing rate and practicing control of stress and prosody', 'Reducing hypernasality with a palatal lift prosthesis', 'C', 'Ataxic dysarthria involves poor coordination, so rate control and prosody work help. It isn''t primarily a weakness or loudness problem.'),
  (250, 'hearing', 'Under ASHA guidelines, how should an SLP screen hearing in a school-age child?', 'Pure tones at 250 Hz only, at 40 dB HL', 'Speech presented at a comfortable listening level', 'Pure tones at 500 Hz at 50 dB HL', 'Pure tones at 1000, 2000, and 4000 Hz at 20 dB HL', 'D', 'ASHA''s screening protocol uses 1000, 2000, and 4000 Hz at 20 dB HL in each ear. A child who misses any frequency is rescreened or referred.'),
  (251, 'child-language-assessment', 'Which profile at 24 months most commonly identifies a toddler as a late talker?', 'Using 100 words and some two-word phrases', 'Pointing to named body parts on request', 'Fewer than 50 words or no two-word combinations', 'Babbling with adult-like intonation', 'C', 'A common late talker criterion is fewer than 50 words or no word combinations at 24 months, with otherwise typical development. The other behaviors are typical at that age.'),
  (252, 'cognitive-treatment', 'A patient with a TBI at Rancho Los Amigos Level VII (automatic, appropriate) gets through daily routines but has trouble with planning and judgment. Which treatment focus is most appropriate?', 'Higher-level reasoning and returning to community and work', 'Basic orientation to person, place, and time', 'Reducing environmental stimulation and noise', 'Teaching reliable yes/no responses with head nods and gestures', 'A', 'At Level VII, routines are automatic but reasoning, judgment, and planning remain weak. Treatment targets those skills and the return to community roles.'),
  (253, 'research-ebp', 'A study reports an effect size (Cohen''s d) of 0.8 for a treatment. How is this usually interpreted?', 'A small effect', 'A large effect', 'No effect', 'A statistically insignificant effect', 'B', 'By Cohen''s guidelines, 0.2 is small, 0.5 is medium, and 0.8 is large. Effect size describes the magnitude of change, separate from statistical significance.'),
  (254, 'ssd-treatment', 'A 4-year-old says words differently each time, even in the same context, with no oral motor signs of apraxia. Which approach is designed for this profile?', 'Minimal pairs', 'Maximal oppositions', 'Core vocabulary approach', 'Cycles approach', 'C', 'The core vocabulary approach (Dodd) targets consistent production of a set of functional words, suited to inconsistent phonological disorder. Contrast approaches are better for consistent errors.'),
  (255, 'motor-speech-assessment', 'Which finding points most strongly to apraxia of speech rather than dysarthria?', 'Consistent weakness of the lips and tongue', 'Groping and distortions that increase with word length', 'Breathy voice and hypernasality throughout speech', 'Reduced loudness that fades with fatigue', 'B', 'Apraxia of speech is a motor planning disorder with groping, slow rate, distorted sounds, and more errors on longer words, without weakness. Weakness, voice changes, and fatigue suggest dysarthria.'),
  (256, 'dysphagia-treatment', 'In the IDDSI framework, which level describes pureed foods and extremely thick drinks?', 'Level 4', 'Level 0', 'Level 2', 'Level 7', 'A', 'IDDSI Level 4 is pureed and extremely thick. Level 0 is thin, Level 2 is mildly thick, and Level 7 is regular food.'),
  (257, 'legislation', 'An adult receives outpatient speech therapy after hospital discharge. Which part of Medicare usually covers these services?', 'Part A', 'Part B', 'Part C only', 'Part D', 'B', 'Medicare Part B covers outpatient therapy. Part A covers inpatient care, and Part D covers prescription drugs.'),
  (258, 'fluency-assessment', 'Which feature best tells cluttering apart from stuttering?', 'Rapid, irregular rate with limited awareness', 'Frequent blocks with high physical tension', 'Strong fear and avoidance of specific words', 'Consistent part-word repetitions at sentence starts', 'A', 'Cluttering involves rapid or irregular rate, many typical disfluencies, and often poor awareness. Tension, blocks, and avoidance are more typical of stuttering.'),
  (259, 'aphasia-treatment', 'To help a patient name a picture, the SLP prompts her to identify the word''s first sound, a rhyming word, and its number of syllables. Which treatment is this?', 'Semantic feature analysis', 'Response elaboration training', 'Supported conversation', 'Phonological components analysis', 'D', 'Phonological components analysis cues the sound structure of the target word. Semantic feature analysis cues meaning.'),
  (260, 'aac', 'Why do AAC systems often emphasize core vocabulary such as ''go'', ''more'', ''not'', and ''help''?', 'These words are the easiest ones to draw', 'Words like these make up most of what people say', 'They are the only words young children need', 'They remove the need for any fringe vocabulary', 'B', 'Core words are high-frequency and flexible across contexts. Fringe words, such as names and topic words, are still needed but used less often.'),
  (261, 'voice-resonance-assessment', 'A patient sustains /s/ for 20 seconds and /z/ for 10 seconds. What does the s/z ratio suggest?', 'Normal voice production for an adult', 'Possible laryngeal pathology affecting closure', 'Poor respiratory support, with normal folds', 'Hypernasal resonance during voicing', 'B', 'The s/z ratio is 2.0. A ratio above about 1.4 suggests the folds aren''t closing efficiently during voicing, since /s/ is voiceless and /z/ is voiced.'),
  (262, 'cultural-linguistic', 'A child learned Spanish and English from birth at the same time. What type of bilingualism is this?', 'Sequential bilingualism', 'Subtractive bilingualism', 'Simultaneous bilingualism', 'Receptive bilingualism', 'C', 'Learning two languages from early childhood, usually before about age 3, is simultaneous bilingualism. Learning a second language after the first is established is sequential.'),
  (263, 'cognitive-assessment', 'A 62-year-old has fluent speech but is gradually losing the meanings of words and objects. She asks, ''What is a giraffe?'' and reads ''yacht'' as it is spelled. Which diagnosis is most likely?', 'Nonfluent variant primary progressive aphasia', 'Logopenic variant primary progressive aphasia', 'Broca''s aphasia from a stroke', 'Semantic variant primary progressive aphasia', 'D', 'Semantic variant PPA involves progressive loss of word and object meaning and surface dyslexia, with fluent speech. The nonfluent variant involves agrammatism and apraxia of speech.'),
  (264, 'autism-treatment', 'Typically developing classmates are taught to start conversations with an autistic student and to respond to his attempts. What is this approach called?', 'Discrete trial training', 'Peer-mediated intervention', 'Video self-modeling', 'Visual scheduling', 'B', 'Peer-mediated intervention trains peers to support social communication in natural settings, which helps generalization. It is an evidence-based practice for autism.'),
  (265, 'cleft-craniofacial', 'A newborn with a cleft palate can''t feed well from a standard bottle. Why, and what helps?', 'His swallow reflex is absent; tube feeding is always needed', 'He has a tongue tie; clipping it solves the problem', 'He''s too weak to suck; thicker milk helps', 'He can''t create suction; a squeeze or specialty bottle helps', 'D', 'The open palate prevents the negative pressure needed for suction, so specialty bottles that deliver milk without suction, with upright positioning, are used. Most infants with clefts can feed by mouth.'),
  (266, 'speech-science', 'How much greater is the sound pressure of a sound at 80 dB SPL than one at 60 dB SPL?', '2 times greater', '20 times greater', '100 times greater', '10 times greater', 'D', 'In SPL, 20 dB equals a tenfold increase in pressure. The intensity of the sound, by contrast, is 100 times greater.'),
  (267, 'literacy', 'An SLP teaches a 7th grader to break ''unhelpful'' into ''un-'', ''help'', and ''-ful'' to work out its meaning and spelling. Which skill is she building?', 'Phonemic awareness', 'Rapid automatized naming', 'Print awareness', 'Morphological awareness', 'D', 'Morphological awareness is knowing the meaningful parts of words, and it supports vocabulary, reading, and spelling in older students. Phonemic awareness concerns individual sounds.'),
  (268, 'counseling-collaboration', 'In Anderson''s continuum of supervision, how does the supervisor''s role change as a supervisee gains skill?', 'It stays the same for the whole relationship', 'It moves from direct feedback toward self-supervision', 'It moves from self-supervision toward closer oversight', 'It ends after the first formal evaluation', 'B', 'Anderson''s model moves through evaluation-feedback, transitional, and self-supervision stages. The goal is an independent, self-evaluating clinician.'),
  (269, 'neuroscience', 'Where is the primary auditory cortex located?', 'The precentral gyrus in the frontal lobe', 'Heschl''s gyrus in the temporal lobe', 'The occipital lobe', 'The postcentral gyrus in the parietal lobe', 'B', 'Heschl''s gyrus, in the superior temporal lobe, is the primary auditory cortex. The precentral gyrus is the primary motor cortex.'),
  (270, 'early-intervention-feeding', 'A 4-year-old with a feeding disorder eats only one brand of plain crackers. The SLP introduces a similar cracker, then one with a slightly different flavor. What is this approach called?', 'Flooding', 'Force feeding', 'Oral motor strengthening', 'Food chaining', 'D', 'Food chaining builds from accepted foods to new ones by changing one feature at a time, such as brand, flavor, or texture. Pressure or force can increase refusal.'),
  (271, 'genetic-syndromes', 'An infant has a distinctive high-pitched, cat-like cry and a deletion on the short arm of chromosome 5. Which syndrome is this?', 'Fragile X syndrome', 'Cri du chat syndrome', 'Williams syndrome', 'Rett syndrome', 'B', 'Cri du chat (5p deletion) is named for its high-pitched cry in infancy and involves intellectual disability and delayed speech and language.'),
  (272, 'head-neck-laryngectomy', 'After a partial glossectomy, a patient has trouble with lingual-palatal sounds. Which option can help him make tongue-palate contact?', 'A palatal augmentation prosthesis', 'An electrolarynx held at the neck', 'A one-way speaking valve', 'A palatal lift prosthesis', 'A', 'A palatal augmentation prosthesis lowers the palate so a smaller tongue can reach it, helping speech and swallowing. A palatal lift raises a weak velum.'),
  (273, 'ssd-assessment', 'A toddler says [gɔgi] for ''doggie''. Which process best describes this error?', 'Velar fronting', 'Velar assimilation', 'Final consonant deletion', 'Reduplication', 'B', 'The alveolar /d/ changes to match the later velar /g/ in the word, so it''s assimilation. Velar fronting would change velars to alveolars, the opposite direction.'),
  (274, 'typical-development', 'Which theory proposes that children are born with an innate capacity for grammar, often called a language acquisition device?', 'Nativist theory', 'Behaviorist theory', 'Social interactionist theory', 'Cognitive theory', 'A', 'Chomsky''s nativist theory holds that children have an innate, universal grammar. Behaviorism (Skinner) attributes language to imitation and reinforcement.'),
  (275, 'fluency-treatment', 'A client who stutters often blocks on bilabial and alveolar stops, with lips and tongue pressed tightly together. Which technique targets this directly?', 'Easy onset of phonation', 'Light articulatory contacts', 'Continuous phonation', 'Rate reduction alone', 'B', 'Light contacts reduce articulatory tension on consonants, especially stops. Easy onset targets the start of voicing, which is more useful for vowel-initial words.'),
  (276, 'anatomy-physiology', 'What is the volume of air moved in and out during a single quiet breath called?', 'Tidal volume', 'Vital capacity', 'Residual volume', 'Inspiratory reserve volume', 'A', 'Tidal volume is the air exchanged in a quiet breath, roughly 500 mL in adults. Vital capacity is the most air that can be exhaled after a maximal inhalation.'),
  (277, 'aphasia-assessment', 'An SLP wants to measure how well a person with aphasia communicates in daily life, such as using the phone or making needs known, rather than measuring language deficits. Which tool fits best?', 'Boston Naming Test, Second Edition (BNT-2)', 'ASHA FACS (Functional Assessment of Communication Skills)', 'Token Test of auditory comprehension', 'Western Aphasia Battery-Revised (WAB-R) Aphasia Quotient', 'B', 'ASHA FACS rates functional communication in daily activities. The Boston Naming Test, Token Test, and WAB-R measure language impairment.'),
  (278, 'child-language-treatment', 'An adolescent with language disorder writes only short, simple sentences. Which technique most directly targets complex syntax?', 'Focused stimulation of plural -s', 'Parallel talk', 'Minimal pair contrasts', 'Sentence combining', 'D', 'Sentence combining teaches students to join simple sentences with conjunctions and embedded clauses, which builds complex syntax in writing. Minimal pairs target speech sounds.'),
  (279, 'dysphagia-assessment', 'A patient has weak jaw closure and trouble chewing solid food. Which cranial nerve is most likely involved?', 'Facial (CN VII)', 'Trigeminal (CN V)', 'Glossopharyngeal (CN IX)', 'Hypoglossal (CN XII)', 'B', 'The trigeminal nerve supplies the muscles of mastication. The facial nerve controls the lips and face, and the hypoglossal nerve controls the tongue.'),
  (280, 'ethics', 'An SLP licensed in Ohio wants to provide telepractice to a client who lives in Texas. Whose licensure requirements apply?', 'The state where the client is located', 'Only Ohio''s, where the SLP is located', 'Neither, because telepractice is exempt', 'Only ASHA certification is needed', 'A', 'Telepractice generally requires licensure (or a valid compact privilege) in the state where the client receives services. ASHA certification doesn''t replace a state license.'),
  (281, 'voice-treatment', 'A high school runner has noisy, tight breathing during races. Laryngoscopy shows her vocal folds closing on inhalation, and asthma medication hasn''t helped. Which treatment is most appropriate?', 'Vocal function exercises done twice a day', 'Hard glottal attacks right before each race begins', 'Strict voice rest throughout the track season', 'Relaxed-throat breathing to use when symptoms start', 'D', 'This is paradoxical vocal fold motion (inducible laryngeal obstruction). SLPs teach relaxed breathing patterns, such as sniffing in and breathing out through pursed lips, to keep the airway open.'),
  (282, 'autism-assessment', 'An SLP is assessing communication in a minimally speaking autistic 6-year-old. Which approach is most appropriate?', 'Relying only on standardized test scores', 'Observation, caregiver report, and trials with AAC', 'Testing in a quiet clinic room in one session', 'Postponing assessment until the child talks', 'B', 'Minimally speaking children often can''t show their abilities on standardized tests, so observation across settings, caregiver input, and AAC trials give a fuller picture. Waiting for speech delays needed support.'),
  (283, 'motor-speech-treatment', 'Which treatment for adult apraxia of speech uses minimal pair contrasts, modeling, articulatory placement cues, and integral stimulation in a response hierarchy?', 'Sound Production Treatment', 'Semantic feature analysis', 'Constraint-induced language therapy', 'Lee Silverman Voice Treatment', 'A', 'Sound Production Treatment moves through a cueing hierarchy to improve sound accuracy in apraxia of speech. Semantic feature analysis targets word retrieval in aphasia.'),
  (284, 'hearing', 'How does a cochlear implant help a person with severe-to-profound sensorineural hearing loss hear?', 'It amplifies sound to make it louder for the remaining hair cells', 'It replaces the middle ear bones', 'It stimulates the auditory nerve directly with electrical signals', 'It sends sound through the skull by bone conduction', 'C', 'A cochlear implant bypasses damaged hair cells and stimulates the auditory nerve electrically. Hearing aids amplify sound, and bone-anchored devices use bone conduction.'),
  (285, 'child-language-assessment', 'Which test measures receptive vocabulary by asking a child to point to one of four pictures named by the examiner?', 'Expressive Vocabulary Test (EVT-3)', 'Goldman-Fristoe Test of Articulation (GFTA-3)', 'Peabody Picture Vocabulary Test (PPVT-5)', 'Boston Naming Test', 'C', 'The PPVT-5 measures receptive vocabulary by picture selection. The EVT-3 is its expressive companion, and the GFTA-3 tests articulation.'),
  (286, 'cognitive-treatment', 'A woman with a TBI keeps missing appointments and forgetting to take her medication. Which approach is most practical?', 'Memory drills of word lists', 'Waiting for her memory to recover on its own', 'Training her to use a smartphone calendar with alarms', 'Having her memorize her whole schedule each morning', 'C', 'Compensatory external aids such as a calendar with alarms support prospective memory in daily life. Word list drills don''t carry over to remembering tasks.'),
  (287, 'research-ebp', 'Which three components make up evidence-based practice as described by ASHA?', 'Research evidence, insurance coverage, and cost', 'Research evidence, clinical expertise, and client perspectives', 'Clinical expertise, test scores, and diagnosis', 'Client perspectives, staff availability, and the clinical setting', 'B', 'EBP combines the best available evidence, clinical expertise, and the client''s values and preferences. Cost and staffing may affect decisions but aren''t part of the EBP framework.'),
  (288, 'ssd-treatment', 'A 3-year-old with a small phonetic inventory isn''t stimulable for most missing sounds. Which approach directly targets this?', 'Stimulability training using characters and gestures', 'Maximal oppositions with nonstimulable sounds', 'Practicing sounds in conversation only', 'Minimal pairs with sounds he can''t yet produce on his own', 'A', 'Stimulability training (Miccio) expands the inventory by making sounds producible through fun, multimodal practice. Contrast approaches assume the child can attempt the sounds.'),
  (289, 'motor-speech-assessment', 'According to ASHA''s 2007 technical report, which group of features has consensus support for diagnosing childhood apraxia of speech?', 'Consistent velar fronting, stopping, and cluster reduction', 'Hypernasality, oral weakness, and frequent drooling', 'Stuttering-like repetitions, prolongations, and blocks', 'Inconsistent errors, disrupted transitions, and atypical prosody', 'D', 'The report names inconsistent errors on consonants and vowels across repetitions, lengthened and disrupted transitions, and inappropriate prosody, especially stress. Consistent pattern errors suggest a phonological disorder.'),
  (290, 'dysphagia-treatment', 'A patient who aspirates thin liquids is unhappy drinking thickened liquids and isn''t drinking enough. Which approach may be considered with strict oral care?', 'Stopping all oral intake permanently', 'Switching to an even thicker liquid level', 'A free water protocol, allowing water between meals', 'Using a straw with all thin liquids to slow intake', 'C', 'Free water protocols allow water between meals after oral care, which can improve hydration and quality of life. Clean water aspirated by a patient with good oral hygiene carries less risk than contaminated secretions.'),
  (291, 'legislation', 'Under IDEA, how often must an IEP be reviewed and a student be reevaluated?', 'Both the IEP and reevaluation every 6 months', 'IEP review every 3 years; reevaluation every year', 'Only when the parent requests a meeting', 'IEP review yearly; reevaluation at least every 3 years', 'D', 'IEPs are reviewed at least annually, and reevaluation happens at least every three years unless the parent and district agree it isn''t needed.'),
  (292, 'fluency-assessment', 'After a stroke, a 60-year-old with no history of stuttering begins repeating sounds on both content and function words, with little anxiety and no change across repeated readings. What is most likely?', 'Neurogenic stuttering', 'Developmental stuttering that went unnoticed', 'Cluttering that began in late adulthood', 'Typical disfluency from word-finding pauses', 'A', 'Neurogenic stuttering begins after brain injury and often affects function words with little anxiety or adaptation. Developmental stuttering begins in childhood.'),
  (293, 'aphasia-treatment', 'An SLP shows the verb ''measure'' and asks the patient who might measure (a carpenter, a chef) and what they measure (wood, flour). Which treatment is this?', 'Verb Network Strengthening Treatment (VNeST)', 'Semantic feature analysis of nouns', 'Melodic intonation therapy', 'Phonological components analysis', 'A', 'VNeST strengthens verbs and their thematic roles (agents and patients) to improve sentence production and word retrieval. It generalizes to untrained verbs.'),
  (294, 'aac', 'Why do some AAC approaches keep each symbol in the same location on the display?', 'Because most devices can''t move symbols', 'To make the display look less cluttered', 'To limit how many words the user can learn', 'So users build automatic motor plans for words', 'D', 'Consistent locations let users find words by motor memory, much like typing. Moving symbols forces them to search visually each time.'),
  (295, 'voice-resonance-assessment', 'A child with enlarged adenoids says ''bobby'' for ''mommy'' and ''dode'' for ''nose''. Which resonance problem is this?', 'Hypernasality', 'Cul-de-sac resonance', 'Hyponasality', 'Nasal emission', 'C', 'Hyponasality is too little nasal resonance on nasal sounds, often from blockage such as large adenoids or congestion. Hypernasality is too much nasal resonance on oral sounds.'),
  (296, 'cultural-linguistic', 'When testing vocabulary in a bilingual child, the SLP gives credit for a concept named in either language. What is this called?', 'Monolingual scoring', 'Dynamic assessment', 'Code-switching', 'Conceptual scoring', 'D', 'Conceptual (total) scoring counts known concepts across both languages. Testing in only one language underestimates a bilingual child''s vocabulary.'),
  (297, 'cognitive-assessment', 'An 80-year-old in the hospital becomes confused over a few hours, with fluctuating attention and alertness. Before the infection she was cognitively normal. What is most likely?', 'Alzheimer''s disease', 'Delirium', 'Frontotemporal dementia', 'Mild cognitive impairment', 'B', 'Delirium has a sudden onset and fluctuating attention, often from illness or medication, and is usually reversible. Dementia develops gradually over months to years.'),
  (298, 'autism-treatment', 'Which strategy is a core part of Pivotal Response Treatment?', 'Rewarding only perfect responses with food', 'Teaching every skill only at a table', 'Child choice, natural rewards, and rewarding attempts', 'Using the same stimulus for every trial in a session', 'C', 'PRT builds motivation through child choice, natural rewards tied to the response, and reinforcing attempts. Mixing tasks and turn-taking are also part of it.'),
  (299, 'cleft-craniofacial', 'A child with a normal palate has nasal emission only on /s/ and /z/, and no hypernasality on other sounds. What is the most likely cause, and how is it treated?', 'Velopharyngeal insufficiency, treated with surgery', 'Enlarged adenoids, treated with removal', 'A learned error, treated with speech therapy', 'Hearing loss, treated with hearing aids', 'C', 'Phoneme-specific nasal emission is a learned articulation error where the child directs airflow through the nose for certain sounds. The velopharynx works normally for other sounds.'),
  (300, 'speech-science', 'Which description fits the sound /ʤ/ as in ''judge''?', 'Voiced postalveolar affricate', 'Voiceless postalveolar fricative', 'Voiced alveolar stop', 'Voiced palatal glide', 'A', '/ʤ/ combines a stop and a fricative at the postalveolar place, with voicing. /ʧ/ is its voiceless counterpart.'),
  (301, 'literacy', 'A child is slow to name rows of familiar colors and letters as quickly as possible. Which reading skill does this rapid automatized naming weakness most predict?', 'Listening comprehension', 'Handwriting', 'Reading fluency', 'Phonological memory span only', 'C', 'RAN speed is a strong predictor of reading fluency and is a separate risk factor from phonological awareness in dyslexia.'),
  (302, 'counseling-collaboration', 'Which counseling approach emphasizes unconditional positive regard, empathy, and genuineness?', 'Behavioral counseling', 'Person-centered (Rogerian) counseling', 'Psychoanalytic therapy', 'Rational emotive behavior therapy', 'B', 'Carl Rogers'' person-centered approach trusts clients to find their own solutions in a supportive, accepting relationship. Behavioral approaches focus on changing behavior through reinforcement.'),
  (303, 'neuroscience', 'Where is the central pattern generator for swallowing located?', 'In the medulla of the brainstem', 'In the cerebellum', 'In the occipital lobe', 'In the spinal cord below the neck', 'A', 'Brainstem swallowing centers in the medulla, including the nucleus tractus solitarius and nucleus ambiguus, coordinate the pharyngeal swallow. A brainstem stroke can cause severe dysphagia.'),
  (304, 'early-intervention-feeding', 'Parents of a 2-year-old late talker attend group sessions to learn strategies such as following their child''s lead and adding language. Which program fits this description?', 'The Lidcombe Program', 'Hanen It Takes Two to Talk', 'LSVT LOUD', 'PROMPT tactile cueing', 'B', 'It Takes Two to Talk is a Hanen parent-training program that teaches responsive interaction strategies. Lidcombe treats stuttering, and PROMPT is a tactile cueing approach.'),
  (305, 'genetic-syndromes', 'A girl develops typically until about 12 months, then loses purposeful hand use and speech and develops repetitive hand-wringing. Which syndrome is most likely?', 'Down syndrome', 'Fragile X syndrome', 'Rett syndrome', 'Cri du chat syndrome', 'C', 'Rett syndrome, usually caused by MECP2 mutations, mainly affects girls and involves regression of hand skills and speech after early typical development. Eye-gaze AAC is often used.'),
  (306, 'head-neck-laryngectomy', 'A patient with a small vocal fold cancer has surgery that removes one vocal fold and part of the thyroid cartilage. Which statement is true?', 'This vertical hemilaryngectomy can keep a natural voice', 'The patient will need TE speech to communicate afterward', 'The patient will breathe only through a stoma', 'Swallowing is never affected by this surgery', 'A', 'Partial laryngectomies such as a vertical hemilaryngectomy keep some laryngeal voice, though it''s often breathy or rough. A total laryngectomy requires alaryngeal speech.'),
  (307, 'ssd-assessment', 'Why should an SLP collect a connected speech sample in addition to giving a single-word articulation test?', 'Single-word tests can''t be given to children under 5', 'Connected speech samples are required to compute standard scores', 'Errors and intelligibility in conversation can differ from single words', 'Single-word tests measure only vowels', 'C', 'Coarticulation, length, and linguistic load in conversation can change accuracy, and intelligibility is best judged in connected speech. Standard scores come from the norm-referenced single-word test, not the sample.'),
  (308, 'typical-development', 'Which language skill continues to develop substantially through adolescence?', 'Using basic subject-verb-object word order', 'Understanding idioms, sarcasm, and other figurative language', 'Marking plurals with -s on regular nouns', 'Producing early sounds such as /p/, /b/, /m/, and /n/ correctly', 'B', 'Figurative language, complex syntax, and abstract vocabulary keep developing into the teen years. The other skills are in place in the preschool years.'),
  (309, 'fluency-treatment', 'A 9-year-old who stutters is being teased at school. Which response is most supported?', 'With the child''s input, educate classmates about stuttering', 'Remove the child from oral activities in the classroom', 'Tell the child to ignore the teasing until it stops', 'Focus therapy only on eliminating his disfluencies', 'A', 'Educating peers and teachers, often with the child helping present, reduces bullying and builds a supportive environment. Removing speaking opportunities can increase avoidance.'),
  (310, 'anatomy-physiology', 'Which extrinsic tongue muscle protrudes the tongue?', 'Styloglossus', 'Hyoglossus', 'Palatoglossus', 'Genioglossus', 'D', 'The genioglossus pulls the tongue forward. The styloglossus retracts and elevates it, and the hyoglossus depresses it.'),
  (311, 'aphasia-assessment', 'The Token Test is mainly used to assess which skill in adults with aphasia?', 'Naming of objects and pictures on confrontation', 'Reading comprehension of short paragraphs', 'Repetition of words and sentences of increasing length', 'Auditory comprehension of commands of increasing complexity', 'D', 'In the Token Test, the patient follows spoken commands involving tokens of different shapes, colors, and sizes, which makes it sensitive to subtle comprehension deficits. It doesn''t test naming or repetition.'),
  (312, 'child-language-treatment', 'A parent reads a picture book with a preschooler, asks open-ended questions, expands the child''s answers, and has the child help tell the story. Which approach is this?', 'Dialogic reading', 'Phonics instruction', 'Drill-based vocabulary practice', 'Sentence imitation', 'A', 'Dialogic reading uses prompts, evaluation, expansion, and repetition (the PEER sequence) to make the child an active storyteller. It is well supported for building preschool vocabulary and oral language.'),
  (313, 'dysphagia-assessment', 'Which factor has been found to be among the strongest predictors of aspiration pneumonia?', 'Having dysphagia without any aspiration', 'Eating a regular diet with thin liquids', 'Depending on others for feeding and oral care', 'Being able to walk independently around the unit', 'C', 'Langmore and colleagues found that dependence for feeding and oral care, along with poor dentition, were strong predictors. Aspiration alone doesn''t always lead to pneumonia.'),
  (314, 'ethics', 'A clinic manager asks an SLP to bill for a 60-minute session when the session actually lasted 30 minutes. What should the SLP do?', 'Bill for 60 minutes because the manager approved it', 'Bill for 45 minutes as a compromise', 'Refuse and bill accurately for the service provided', 'Bill for 60 minutes but note the real time in the chart', 'C', 'Misrepresenting services in billing is fraud and violates the Code of Ethics. Following a supervisor''s direction doesn''t excuse it.'),
  (315, 'voice-treatment', 'In gender-affirming voice training, which factor besides pitch has a large effect on how listeners perceive a voice''s gender?', 'Vital capacity of the lungs', 'Resonance (vocal tract formant frequencies)', 'Jaw strength', 'The number of words used per sentence', 'B', 'Resonance, shaped by vocal tract length and configuration, strongly affects gender perception even when pitch is changed. Lung capacity has little effect.'),
  (316, 'autism-assessment', 'Autism is diagnosed about how many times more often in boys than in girls, according to recent CDC surveillance?', 'About the same rate', 'About 10 times', 'About 3 to 4 times', 'About 20 times', 'C', 'CDC data show autism identified about 3 to 4 times more often in boys. Girls may be underidentified because of differences in how autism presents.'),
  (317, 'motor-speech-treatment', 'A man with ALS has severe dysarthria but can still point. Which strategy can make his speech more intelligible?', 'Oral strengthening exercises to the point of fatigue', 'Speaking faster to get more words out per breath', 'Pointing to the first letter of each word as he says it', 'Reducing the pauses between his words', 'C', 'Alphabet supplementation slows rate and gives listeners the first letter of each word, improving intelligibility. Strengthening exercises can worsen fatigue in ALS.'),
  (318, 'hearing', 'Before each session, an SLP asks a child with hearing aids to respond to /m/, /u/, /a/, /i/, /ʃ/, and /s/. What is the purpose?', 'To check that the child detects sounds across frequencies', 'To test the child''s articulation of six sounds', 'To diagnose the type and degree of the child''s hearing loss', 'To measure the child''s receptive vocabulary', 'A', 'The Ling Six Sound Test covers low to high frequencies, so it quickly checks that hearing aids or implants are working. It isn''t a diagnostic test.'),
  (319, 'child-language-assessment', 'In narrative assessment, what does macrostructure refer to?', 'The average number of words in each sentence of the story', 'The story''s overall organization, such as problem and resolution', 'Use of conjunctions, pronouns, and other cohesive ties', 'Correct use of grammatical morphemes across the whole story', 'B', 'Macrostructure is the story grammar or overall organization. Microstructure covers the language within the story, such as sentence length, conjunctions, and grammar.'),
  (320, 'cognitive-treatment', 'Which advice should an SLP give to caregivers of a person with moderate dementia?', 'Ask open-ended questions to test her memory', 'Correct every factual error she makes', 'Speak quickly so she doesn''t lose interest', 'Use short sentences and offer choices', 'D', 'Simplifying language and offering choices reduce demands on memory and language. Quizzing and correcting often cause frustration and withdrawal.'),
  (321, 'research-ebp', 'A researcher concludes that a treatment works when it actually has no effect. What kind of error is this?', 'Type II error', 'Type I error', 'Sampling error', 'Measurement bias', 'B', 'A Type I error is rejecting a true null hypothesis, a false positive. A Type II error is missing a real effect.'),
  (322, 'ssd-treatment', 'An SLP works on /s/ until the child reaches 90 percent in conversation before starting /r/. What is this goal attack strategy called?', 'Vertical', 'Horizontal', 'Cyclical', 'Random', 'A', 'A vertical strategy targets one goal to criterion before moving on. A horizontal strategy works on several goals at once, and cyclical strategies rotate goals on a schedule.'),
  (323, 'motor-speech-assessment', 'During alternating motion rate tasks (rapid /pʌpʌpʌ/), which finding is most characteristic of ataxic dysarthria?', 'Slow but regular rhythm', 'Very fast, accelerating repetitions', 'Irregular rate and rhythm', 'Perfectly normal performance', 'C', 'Irregular AMRs reflect the incoordination of ataxic dysarthria. Spastic dysarthria tends to give slow, regular AMRs, and hypokinetic dysarthria can give fast, blurred ones.'),
  (324, 'dysphagia-treatment', 'Which treatment has research support for improving cough strength and airway protection in people with Parkinson''s disease?', 'Tongue-tip lateralization drills', 'Thermal-tactile stimulation alone', 'Lip-closure exercises with a resistance button', 'Expiratory muscle strength training (EMST)', 'D', 'EMST uses a resistance device to train expiratory force, and studies show better cough and Penetration-Aspiration Scale scores in Parkinson''s disease. Lip exercises don''t target airway protection.'),
  (325, 'legislation', 'Under IDEA 2004, which process may schools use to help identify specific learning disabilities instead of relying only on an IQ-achievement discrepancy?', 'Least restrictive environment', 'Response to intervention (RTI)', 'Prior written notice', 'Extended school year', 'B', 'IDEA 2004 lets schools use a student''s response to research-based, tiered intervention as part of identifying learning disabilities. RTI and MTSS are also used to give early support before a referral.'),
  (326, 'fluency-assessment', 'A person who stutters reads the same passage five times, and stuttering decreases with each reading. What is this called?', 'Adaptation effect', 'Consistency effect', 'Secondary behavior', 'Expectancy', 'A', 'The adaptation effect is reduced stuttering over repeated readings. The consistency effect is stuttering on the same words across readings.'),
  (327, 'aphasia-treatment', 'For a patient with agrammatic aphasia, an SLP trains complex structures such as object relative clauses, expecting gains on simpler related structures. Which approach is this?', 'Script training', 'Response elaboration training', 'Melodic intonation therapy', 'Treatment of underlying forms', 'D', 'Treatment of underlying forms (Thompson) trains linguistically complex sentences, which tends to generalize to simpler related forms. The reverse direction generalizes less.'),
  (328, 'aac', 'How does Medicare usually classify a speech-generating device for coverage?', 'As durable medical equipment, requiring an SLP evaluation', 'As a prescription drug benefit under Medicare Part D', 'As a hearing aid, a device Medicare excludes', 'As an experimental device that Medicare won''t cover', 'A', 'Medicare covers speech-generating devices as durable medical equipment when medically necessary, with an SLP evaluation and a physician''s order.'),
  (329, 'voice-resonance-assessment', 'What does a nasometer measure?', 'Nasalance, the share of acoustic energy from the nose', 'Vocal fold vibration during connected speech', 'Lung volume used during speech', 'Air pressure inside the mouth during stop consonants', 'A', 'The nasometer compares sound energy from the nose and mouth and gives a nasalance score. High scores on oral passages suggest hypernasality.'),
  (330, 'cultural-linguistic', 'Parents who speak Korean at home ask if they should switch to English only because their child has a language disorder. What is the best advice?', 'Keep using Korean, the language they know best', 'Switch to English only to avoid confusion', 'Stop talking to the child until therapy helps', 'Use only sign language at home', 'A', 'Bilingualism doesn''t cause or worsen language disorders. Parents give the richest input in the language they know best, and keeping it supports family connection.'),
  (331, 'cognitive-assessment', 'A man with a frontal lobe TBI scores within normal limits on structured cognitive tests but can''t manage his tasks at work. What best explains this?', 'The tests were scored or administered incorrectly', 'Testing supplies the structure he can''t provide on his own', 'He is exaggerating his symptoms at work', 'Frontal lobe injuries don''t affect daily functioning', 'B', 'Quiet, examiner-guided testing supplies external structure, which can hide executive function deficits. Functional, real-world assessment is needed.'),
  (332, 'autism-treatment', 'A school proposes facilitated communication, in which a facilitator supports a nonspeaking student''s hand as she types. What is ASHA''s position?', 'It is a recommended AAC method for nonspeaking students', 'It is acceptable if the facilitator is trained', 'It isn''t supported, since facilitators author the messages', 'It is fine for academic work but not for personal decisions', 'C', 'Controlled studies show that facilitators, not the users, author the messages. ASHA opposes its use, and similar concerns apply to Rapid Prompting Method.'),
  (333, 'cleft-craniofacial', 'After palate repair, a 5-year-old still has consistent hypernasality because of a short velum, confirmed by nasopharyngoscopy. What is the usual next step?', 'More therapy focused on blowing exercises', 'Referral for secondary surgery, such as a pharyngeal flap', 'Waiting until adolescence to reassess', 'Teaching louder speech to mask the resonance problem', 'B', 'Hypernasality from a structural gap needs physical management, such as a pharyngeal flap, sphincter pharyngoplasty, or palate re-repair. Therapy can''t close a structural gap.'),
  (334, 'speech-science', 'Which English vowel is high, back, and rounded?', '/i/ as in ''beet''', '/æ/ as in ''bat''', '/ɑ/ as in ''father''', '/u/ as in ''boot''', 'D', '/u/ is high, back, and rounded. /i/ is high and front, /æ/ is low and front, and /ɑ/ is low and back.'),
  (335, 'literacy', 'An SLP explicitly teaches a student a planning and revising strategy for essays, models it, and gradually hands over responsibility. Which approach is this?', 'Dialogic reading', 'Self-Regulated Strategy Development (SRSD)', 'Phonological awareness training', 'Visual-perceptual and tracking training', 'B', 'SRSD teaches writing strategies with modeling, memorization, and self-regulation, and it has strong research support. Dialogic reading builds oral language in young children.'),
  (336, 'counseling-collaboration', 'The mother of a 4-year-old who stutters says, ''It''s my fault. I must have caused this.'' What is the best response?', 'Agree that her parenting style may have caused it', 'Acknowledge her feelings and explain parents don''t cause it', 'Tell her not to worry, then change the subject', 'Suggest she talk much less with her child at home for a while', 'B', 'Counseling combines empathy with accurate information. Research shows stuttering has strong genetic and neurological roots and isn''t caused by parenting.'),
  (337, 'neuroscience', 'In multiple sclerosis, damage to myelin mainly affects which aspect of neural function?', 'The speed of nerve signal conduction', 'Production of dopamine in the midbrain', 'The number of fibers in each muscle', 'Blood flow through the cerebral arteries', 'A', 'Myelin speeds conduction along axons, so demyelination slows or blocks signals. MS can cause mixed dysarthria, often with ataxic and spastic features.'),
  (338, 'early-intervention-feeding', 'A 5-month-old with poor weight gain often coughs and has noisy breathing during bottle feeds. What is the most appropriate next step?', 'Refer for an instrumental swallow study', 'Switch to thicker formula without testing', 'Begin solid foods early', 'Wait until the infant is a year old', 'A', 'Infants often aspirate silently, and clinical signs can''t confirm what''s happening. A videofluoroscopic study shows whether aspiration occurs and which changes help.'),
  (339, 'genetic-syndromes', 'A child has coloboma of the eye, a heart defect, blocked nasal passages (choanal atresia), growth delays, and ear malformations with hearing loss. Which condition does this suggest?', 'Williams syndrome', 'CHARGE syndrome', 'Prader-Willi syndrome', 'Angelman syndrome', 'B', 'CHARGE stands for coloboma, heart defects, atresia of the choanae, restricted growth and development, genital anomalies, and ear anomalies. Hearing, vision, and feeding problems are common.'),
  (340, 'head-neck-laryngectomy', 'A man with a total laryngectomy stops breathing in a restaurant. How must rescue breaths be given?', 'Through the mouth while pinching the nose', 'Through the nose only', 'Rescue breaths can''t be given after laryngectomy', 'Through the stoma in his neck', 'D', 'After a total laryngectomy, the trachea opens only at the stoma and no longer connects to the mouth or nose. Patients are encouraged to carry neck-breather identification.'),
  (341, 'ssd-assessment', 'Which group of English consonants is typically acquired earliest?', '/θ, ð, ʒ/', '/r, l/', '/ʧ, ʤ, ʃ/', '/m, p, b, n/', 'D', 'Nasals and bilabial stops are among the earliest sounds acquired. Interdental fricatives, /ʒ/, liquids, and affricates are among the later ones.'),
  (342, 'typical-development', 'A 12-month-old points at an airplane, then looks back at the parent''s face to share the moment. Which behavior is this?', 'Protoimperative pointing', 'Cooing', 'Delayed echolalia', 'Protodeclarative pointing', 'D', 'Pointing to share interest, with gaze checking, is protodeclarative and reflects joint attention. Protoimperative pointing is used to request an object.'),
  (343, 'fluency-treatment', 'What is the main goal of stuttering modification therapy?', 'Replacing stuttering with a fluent, prolonged speech pattern', 'Stuttering more easily, with less tension and avoidance', 'Eliminating every stuttering moment', 'Reducing speaking rate in all situations', 'B', 'Stuttering modification (Van Riper) aims for easier, less tense stuttering and less fear and avoidance, not complete fluency. A new prolonged speech pattern is the aim of fluency shaping.'),
  (344, 'anatomy-physiology', 'How does the breathing cycle change from quiet breathing to speech breathing?', 'Inhalation becomes much shorter and exhalation much longer', 'Inhalation and exhalation become about equal in length', 'Exhalation becomes shorter than inhalation', 'The cycle doesn''t change', 'A', 'In quiet breathing, inhalation takes about 40 percent of the cycle and exhalation about 60 percent. In speech, inhalation drops to about 10 percent and exhalation rises to about 90 percent.'),
  (345, 'aphasia-assessment', 'Aphasia caused by stroke most often results from blockage of which artery?', 'Left anterior cerebral artery', 'Right posterior cerebral artery', 'Basilar artery', 'Left middle cerebral artery', 'D', 'The left middle cerebral artery supplies the perisylvian language areas, including Broca''s and Wernicke''s areas. The anterior cerebral artery supplies the medial frontal lobes.'),
  (346, 'child-language-treatment', 'The parent of a 3-year-old with language delay asks whether to speak in short telegraphic phrases such as ''Mommy go car'' so the child can copy them. What is the best advice?', 'Use short but grammatically complete sentences', 'Yes, telegraphic phrases are easiest to imitate', 'Use long, complex sentences to stretch the child', 'Speak only in single words', 'A', 'Research doesn''t support telegraphic input. Short, grammatical sentences give the child correct models of the grammatical morphemes they need to learn.'),
  (347, 'dysphagia-assessment', 'What is the MBSImP?', 'A bedside water swallow screening test', 'A diet-level framework for food and drink textures', 'A patient-reported quality of life survey', 'A standardized protocol for scoring swallow physiology', 'D', 'The Modified Barium Swallow Impairment Profile standardizes how bolus types are given and how components of swallow physiology are scored. IDDSI is the diet framework.'),
  (348, 'ethics', 'When a graduate student clinician treats a client in a university clinic, who is professionally responsible for the services?', 'The student, once they have completed coursework', 'The client''s family', 'The certified SLP who supervises the student', 'The university''s dean', 'C', 'Supervising SLPs keep responsibility for the services students provide and must supervise at a level that protects the client. The student doesn''t hold independent responsibility.'),
  (349, 'voice-treatment', 'Why do semi-occluded vocal tract exercises such as straw phonation help voice production?', 'Back pressure eases vibration and reduces impact on the folds', 'They strengthen the lips by blowing against resistance', 'They block airflow completely so the vocal folds can rest', 'They raise the larynx to brighten vocal resonance', 'A', 'Partly closing the mouth raises supraglottic pressure, which helps the folds vibrate efficiently with less collision force. The goal isn''t lip strength.'),
  (350, 'autism-assessment', 'Which speech feature is often described in autistic speakers?', 'Consistent backing of alveolar sounds', 'Atypical prosody, such as flat or sing-song intonation', 'Hypernasality from velopharyngeal weakness', 'Breathy voice from unilateral vocal fold paralysis', 'B', 'Prosodic differences in pitch, stress, and rhythm are commonly reported in autism. The other features point to other disorders.'),
  (351, 'motor-speech-treatment', 'A newly diagnosed person with ALS has only mild dysarthria. What is the most important early step for the SLP to discuss?', 'Intensive strengthening of the tongue and lips', 'Waiting to discuss AAC until speech is unintelligible', 'Message or voice banking and planning for AAC', 'Teaching esophageal speech', 'C', 'Because ALS is progressive, recording messages or voice while speech is still clear and planning AAC early prevent a gap in communication. Strengthening exercises aren''t recommended.'),
  (352, 'hearing', 'Otoacoustic emissions (OAEs), used in newborn hearing screening, mainly reflect the function of which structure?', 'Outer hair cells of the cochlea', 'The auditory cortex in the temporal lobe', 'The ossicles of the middle ear', 'The eighth cranial nerve and brainstem pathway', 'A', 'OAEs are sounds produced by healthy outer hair cells. Present OAEs don''t rule out auditory neuropathy, which affects the nerve and is tested with ABR.'),
  (353, 'child-language-assessment', 'A child''s mean length of utterance is 3.4 morphemes. Which of Brown''s stages does this correspond to?', 'Stage I', 'Stage II', 'Stage V', 'Stage IV', 'D', 'Brown''s ranges are Stage I 1.0 to 2.0, II 2.0 to 2.5, III 2.5 to 3.0, IV 3.0 to 3.75, and V 3.75 to 4.5. An MLU of 3.4 falls in Stage IV.'),
  (354, 'cognitive-treatment', 'A high school student with a concussion has headaches and trouble concentrating. What should the SLP recommend in a gradual return-to-learn plan?', 'Full course load immediately to prevent falling behind', 'Temporary accommodations such as reduced workload and extra time', 'No school until all symptoms are gone, for at least two months', 'Intensive memory drills during school hours', 'B', 'Return-to-learn plans add temporary academic supports while symptoms are present and step them back as the student recovers. Long, complete rest and immediate full workload are both discouraged.'),
  (355, 'research-ebp', 'A study compares two vocabulary treatments and measures the number of words children learn. What is the dependent variable?', 'The number of words learned', 'The type of treatment', 'The children''s ages', 'The number of sessions', 'A', 'The dependent variable is the outcome measured. The treatment type is the independent variable the researcher manipulates.'),
  (356, 'ssd-treatment', 'A child who produces /t/ correctly but can''t yet say /s/ is asked to say /t/ and hold the airflow after it (''tsss''), then gradually drop the /t/. Which technique is this?', 'Auditory bombardment with /s/ words', 'A minimal pair contrast of /t/ and /s/ words', 'Shaping from a sound the child can already produce', 'Core vocabulary practice of whole functional words', 'C', 'Shaping (successive approximation, or phonetic derivation) builds a new sound from a related sound the child already has, here using the alveolar /t/ to reach /s/. Auditory bombardment gives listening input without production.'),
  (357, 'motor-speech-assessment', 'A patient''s speech is clear at the start of a conversation but becomes progressively breathy, hypernasal, and imprecise as she keeps talking, and improves after rest. Which condition should the SLP suspect?', 'Parkinson''s disease', 'Cerebellar stroke', 'Myasthenia gravis', 'Huntington''s disease', 'C', 'Fatigable flaccid dysarthria that recovers with rest is a hallmark of myasthenia gravis, a neuromuscular junction disorder. The SLP should refer for medical evaluation.'),
  (358, 'dysphagia-treatment', 'A patient with a supraglottic laryngectomy needs closure at the entrance to the airway, not just at the vocal folds. Which maneuver adds effort to a breath hold to tilt the arytenoids forward?', 'Super-supraglottic swallow', 'Supraglottic swallow', 'Mendelsohn maneuver', 'Chin tuck', 'A', 'The super-supraglottic swallow adds an effortful bear-down to the breath hold, tilting the arytenoids forward to close the laryngeal entrance. The plain supraglottic swallow closes mainly at the vocal folds.'),
  (359, 'legislation', 'What standard for an IEP did the U.S. Supreme Court set in Endrew F. v. Douglas County School District (2017)?', 'It must be reasonably calculated to enable appropriate progress', 'It must be designed to maximize the child''s full potential', 'It must provide just more than minimal educational benefit', 'It must place every child in general education full time', 'A', 'The Court rejected a ''merely more than de minimis'' standard and required appropriately ambitious goals. It didn''t require maximizing potential.'),
  (360, 'fluency-assessment', 'An SLP wants to learn how a 5-year-old who stutters feels about talking. Which tool is designed for this?', 'KiddyCAT (Communication Attitude Test)', 'Stuttering Severity Instrument (SSI-4)', 'OASES-A for adults', 'Percent syllables stuttered', 'A', 'The KiddyCAT measures young children''s attitudes toward their own speech. The SSI-4 and %SS measure observable stuttering, and the OASES-A is for adults.'),
  (361, 'aphasia-treatment', 'Which approach to aphasia care puts the person''s chosen life goals and participation in daily activities at the center of treatment?', 'Constraint-induced language therapy only', 'Life Participation Approach to Aphasia (LPAA)', 'Repeated confrontation naming drills', 'Treatment of underlying forms only', 'B', 'LPAA focuses on helping people with aphasia reengage in life activities they choose, including environmental and social supports. Impairment-focused treatments may be part of it but aren''t its center.'),
  (362, 'aac', 'On a client''s tablet AAC app, pressing the ''food'' symbol opens a new page of food symbols. What type of display is this?', 'Static display', 'Unaided display', 'Dynamic display', 'Visual scene display only', 'C', 'A dynamic display changes when a symbol is selected, linking pages of vocabulary. A static display, such as a printed board, shows the same symbols all the time.'),
  (363, 'voice-resonance-assessment', 'What is a typical maximum phonation time for a healthy adult sustaining a vowel?', 'About 2 to 3 seconds', 'About 5 to 8 seconds', 'About 15 to 25 seconds or longer', 'At least 90 seconds or longer', 'C', 'Healthy adults usually sustain a vowel for 15 to 25 seconds or more, with men often longer. A very short time can reflect poor closure or respiratory support.'),
  (364, 'cultural-linguistic', 'A 9-year-old who started school in English has lost much of her ability to speak her home language, Arabic. What is this process called?', 'Additive bilingualism from school', 'Simultaneous bilingual development', 'Code-switching between her languages', 'Subtractive bilingualism (first language loss)', 'D', 'Subtractive bilingualism is when a second language replaces the first rather than adding to it. It can harm family communication and be mistaken for a disorder.'),
  (365, 'cognitive-assessment', 'Which description best fits mild cognitive impairment?', 'Severe memory loss that prevents independent living', 'Sudden confusion with fluctuating attention', 'Decline beyond normal aging, with daily function largely intact', 'Normal age-related forgetfulness, with no measurable decline', 'C', 'MCI involves measurable cognitive decline beyond normal aging without a major loss of independence. Dementia involves significant interference with daily function.')
) as v (seq, slug, question, a, b, c, d, correct, explanation)
join public.praxis_categories c on c.exam = 'praxis-slp' and c.slug = v.slug;
